#[test]
fn test_nontrivial_drop_fails_soft_with_honest_panic_obligation() {
    let drop_ty = Ty::Adt {
        adt_kind: None,
        layout: None,
        variants: Vec::new().into(),
        name: "NeedsDrop".to_string(),
        fields: vec![("x".to_string(), Ty::i64())].into(),
        disc_index_safe: false,
        faithful_enum_repr: None,
        enum_layout: None,
        arbitrary_precision: None,
        validity_wrapper: None,
    };
    let func = VerifiableFunction {
        name: "drop_nontrivial_fn".to_string(),
        def_path: "test::drop_nontrivial_fn".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: drop_ty, name: Some("x".into()) },
            ],
            blocks: vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Drop {
                        unwind: UnwindEdge::Unreachable,
                        place: Place::local(1),
                        target: BlockId(1),
                        span: SourceSpan::default(),
                    },
                },
                TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 0,
            return_ty: Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };

    // FAIL-SOFT (was fail-closed-by-Err): a Drop with unproven-panic-free glue
    // no longer fails the whole lowering — it lowers to the audited may-panic
    // encoding (Assert(false)+NoPanic marker + ONE marked PanicFreedom
    // obligation + the Br to the target). The fail-CLOSED property this test
    // protects is unchanged: the drop is never a silent no-op branch — its
    // possible panic stays reachable and carries an honest obligation.
    let module = lower_to_trust_ir(&func).expect("nontrivial Drop must lower fail-soft, not Err");
    assert_valid_module(&module);
    let insts: Vec<_> = module.functions[0].blocks.iter().flat_map(|b| b.body.iter()).collect();
    assert_eq!(
        no_panic_false_assert_count(&module),
        1,
        "expected exactly one Assert(false)+NoPanic may-panic marker for the drop glue"
    );
    assert!(
        insts.iter().any(|n| matches!(n.inst, Inst::Br { .. })),
        "the drop must still branch to its target"
    );
    assert_eq!(
        module
            .proof_obligations
            .iter()
            .filter(|o| {
                o.kind == trust_ir::ObligationKind::PanicFreedom
                    && o.description
                        .starts_with(trust_types::assumption::DROP_GLUE_ASSUMPTION_PREFIX)
            })
            .count(),
        1,
        "expected exactly one marked drop-glue PanicFreedom obligation"
    );
    assert_eq!(
        module
            .proof_obligations
            .iter()
            .filter(|obligation| obligation.kind == trust_ir::ObligationKind::PanicFreedom)
            .count(),
        2,
        "an unknown Drop must emit exactly one site row plus one counted function carrier"
    );
    assert_eq!(
        module
            .proof_obligations
            .iter()
            .filter(|obligation| obligation.kind == trust_ir::ObligationKind::PanicFreedom)
            .filter_map(|obligation| obligation.source.as_ref())
            .filter(|source| source.source_id.starts_with("mir-assertions:"))
            .count(),
        1,
        "the fail-soft site must have exactly one counted whole-function carrier"
    );
}

// ---------------------------------------------------------------------------
// Drop-glue classifier: structural panic-free-drop proofs (vs. the honest
// fail-soft assumption row above). See `is_panic_free_drop_ext` in lower.rs.
// ---------------------------------------------------------------------------

/// Build a one-block `VerifiableFunction` that drops a single local of `drop_ty`
/// and returns. Shared by the drop-glue classifier tests below.
fn drop_glue_test_fn(drop_ty: Ty) -> VerifiableFunction {
    VerifiableFunction {
        name: "drop_glue_fn".to_string(),
        def_path: "test::drop_glue_fn".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: drop_ty, name: Some("v".into()) },
            ],
            blocks: vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Drop {
                        unwind: UnwindEdge::Unreachable,
                        place: Place::local(1),
                        target: BlockId(1),
                        span: SourceSpan::default(),
                    },
                },
                TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 0,
            return_ty: Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    }
}

/// Count of `assumption:drop-glue` `PanicFreedom` obligations recorded on `module`.
fn drop_glue_assumption_count(module: &trust_ir::Module) -> usize {
    module
        .proof_obligations
        .iter()
        .filter(|o| {
            o.kind == trust_ir::ObligationKind::PanicFreedom
                && o.description.starts_with(trust_types::assumption::DROP_GLUE_ASSUMPTION_PREFIX)
        })
        .count()
}

/// Count generic-parameter drop boundaries reclassified as expected-absent. They retain the
/// reachable `Assert(false)+NoPanic` marker and remain unproved; only explicit advisory policy
/// may later record them as assumptions.
fn expected_absent_drop_count(module: &trust_ir::Module) -> usize {
    module
        .proof_obligations
        .iter()
        .filter(|obligation| {
            obligation.kind == trust_ir::ObligationKind::PanicFreedom
                && obligation
                    .description
                    .starts_with(trust_types::assumption::EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX)
                && obligation.description.contains("drop glue for generic parameter")
        })
        .count()
}

/// `true` if any instruction in `module`'s sole function is the drop-glue
/// `Assert(false)+NoPanic` may-panic marker.
///
/// Build-7 sharpening: the check resolves the asserted condition to its defining
/// `Const` and requires it to be the constant `false`. A PROVEN drop now records
/// its discharge as `Assert(true)+NoPanic` (a trivially-valid check paired with a
/// named, dischargeable obligation row — see the Drop arm in lower.rs), which is
/// NOT a may-panic marker; only the reachable-panic `Assert(false)` form is.
fn drop_glue_marker_count(module: &trust_ir::Module) -> usize {
    no_panic_false_assert_count(module)
}

fn has_drop_glue_marker(module: &trust_ir::Module) -> bool {
    drop_glue_marker_count(module) != 0
}

/// Count of the Build-7 DISCHARGED drop-glue rows on `module`: named `PanicFreedom`
/// obligations recording a classifier-proven panic-free drop. These carry the
/// human-readable justification and NO assumption prefix (they flow through normal
/// verdict discharge — never an unproved assumption-panic row).
fn drop_glue_discharged_count(module: &trust_ir::Module) -> usize {
    module
        .proof_obligations
        .iter()
        .filter(|o| {
            o.kind == trust_ir::ObligationKind::PanicFreedom
                && o.description.contains("drop glue for")
                && o.description.contains("— discharged: proven panic-free")
                && !o.description.starts_with(trust_types::assumption::DROP_GLUE_ASSUMPTION_PREFIX)
        })
        .count()
}

#[test]
fn test_drop_glue_proves_for_result_of_plain_struct_and_fieldless_enum() {
    // `Rat` — a plain-data struct with NO user `Drop` impl (as the compiler's
    // `collect_structural_drop_adts` would certify via `!has_dtor`).
    let rat_ty = Ty::adt(
        "myapp::Rat",
        vec![("numerator".to_string(), Ty::i64()), ("denominator".to_string(), Ty::i64())],
    );
    // `CheckError` — a FIELDLESS user enum, also compiler-certified no-`Drop`.
    let check_error_ty = Ty::Adt {
        adt_kind: None,
        layout: None,
        name: "myapp::CheckError".to_string(),
        fields: vec![("__tag".to_string(), Ty::i64())].into(),
        variants: vec![
            trust_types::VariantDef {
                name: "BadNumerator".to_string(),
                discriminant: 0,
                fields: vec![],
            },
            trust_types::VariantDef {
                name: "BadDenominator".to_string(),
                discriminant: 1,
                fields: vec![],
            },
        ]
        .into(),
        disc_index_safe: false,
        faithful_enum_repr: None,
        enum_layout: None,
        arbitrary_precision: None,
        validity_wrapper: None,
    };
    // `core::result::Result<Rat, CheckError>` — the vetted std payload enum,
    // flattened exactly as the real extractor's `lower_enum_adt` shapes it
    // (`__tag` + one `__v{idx}_{field}` entry per variant field).
    let result_ty = Ty::Adt {
        adt_kind: None,
        layout: None,
        name: "core::result::Result".to_string(),
        fields: vec![
            ("__tag".to_string(), Ty::i64()),
            ("__v0_0".to_string(), rat_ty.clone()),
            ("__v1_0".to_string(), check_error_ty.clone()),
        ]
        .into(),
        variants: vec![
            trust_types::VariantDef {
                name: "Ok".to_string(),
                discriminant: 0,
                fields: vec![("0".to_string(), rat_ty)],
            },
            trust_types::VariantDef {
                name: "Err".to_string(),
                discriminant: 1,
                fields: vec![("0".to_string(), check_error_ty)],
            },
        ]
        .into(),
        disc_index_safe: false,
        faithful_enum_repr: None,
        enum_layout: None,
        arbitrary_precision: None,
        validity_wrapper: None,
    };

    let structural_drop: std::collections::HashSet<String> =
        ["myapp::Rat".to_string(), "myapp::CheckError".to_string()].into_iter().collect();
    let module = lower_to_trust_ir_functions_with_context(
        "test_mod",
        &[drop_glue_test_fn(result_ty)],
        &std::collections::HashSet::new(),
        &structural_drop,
    )
    .expect("Result<Rat, CheckError> drop must lower");
    assert_valid_module(&module);

    assert!(
        !has_drop_glue_marker(&module),
        "a provably panic-free drop must NOT emit the Assert(false)+NoPanic marker"
    );
    let insts: Vec<_> = module.functions[0].blocks.iter().flat_map(|b| b.body.iter()).collect();
    assert!(
        insts.iter().any(|n| matches!(n.inst, Inst::Br { .. })),
        "the drop must still branch to its target"
    );
    assert_eq!(
        drop_glue_assumption_count(&module),
        0,
        "a provably panic-free drop must NOT record a drop-glue assumption row"
    );
    // Build-7 row-classification fix: the proof is RECORDED as one named,
    // dischargeable row (constant-false panic condition — flows through normal
    // verdict discharge), never left as an invisible bare `Br`.
    assert_eq!(drop_glue_discharged_count(&module), 1);
    // The row names the type as Rust spells it, not the bridge `Ty`'s Debug dump
    // (`Adt { name: .., fields: [..] }`, which ran to dozens of lines per row).
    let discharged: Vec<&str> = module
        .proof_obligations
        .iter()
        .map(|o| o.description.as_str())
        .filter(|d| d.contains("— discharged: proven panic-free"))
        .collect();
    assert!(
        discharged[0].starts_with("drop glue for `core::result::Result` — discharged"),
        "the discharged row must name the Rust type: {discharged:?}"
    );
    assert!(!discharged[0].contains("Adt {"), "no Debug dump in the row: {discharged:?}");
}

#[test]
fn test_drop_glue_kept_for_adt_with_user_drop_impl() {
    // `PanickyGuard` has a real user `Drop` impl. The compiler's
    // `collect_structural_drop_adts` would NOT include it (`has_dtor` is true), so
    // its name is deliberately ABSENT from `structural_drop` below even though the
    // set is non-empty (proving MEMBERSHIP — not merely "some set was passed" — is
    // what unlocks the proof).
    let guard_ty = Ty::adt("myapp::PanickyGuard", vec![("x".to_string(), Ty::i64())]);
    let structural_drop: std::collections::HashSet<String> =
        ["myapp::SomeOtherCertifiedType".to_string()].into_iter().collect();

    let module = lower_to_trust_ir_functions_with_context(
        "test_mod",
        &[drop_glue_test_fn(guard_ty)],
        &std::collections::HashSet::new(),
        &structural_drop,
    )
    .expect("uncertified Drop must lower fail-soft, not Err");
    assert_valid_module(&module);

    assert!(
        has_drop_glue_marker(&module),
        "a type with a possible user Drop impl must keep the Assert(false)+NoPanic marker"
    );
    assert_eq!(
        drop_glue_assumption_count(&module),
        1,
        "a type with a possible user Drop impl must keep exactly one drop-glue assumption row"
    );
}

// ---------------------------------------------------------------------------
// Drop-glue: VARIANT-SENSITIVE accounting.
//
// An enum's drop glue is a SWITCH on the discriminant. The blanket per-ADT row
// charged every arm, including arms the tag provably rules out and arms whose
// payload holds nothing droppable. The lane below charges each arm separately.
// SOUNDNESS is pinned by the negative twins: an unknown tag, an escaping
// borrow, and a constant-`Err` tag must all still charge the `Err` arm.
// ---------------------------------------------------------------------------

/// The `Err` payload used by the variant tests: a plain user ADT that is NOT in
/// `structural_drop`, so the classifier cannot prove its drop panic-free and the
/// `Err` arm is genuinely undischargeable.
fn variant_test_err_payload() -> Ty {
    Ty::adt("myapp::PanickyErr", vec![("x".to_string(), Ty::i64())])
}

/// `core::result::Result<(), myapp::PanickyErr>`, flattened exactly as the real
/// extractor's `lower_enum_adt` shapes it (`__tag` + one `__v{idx}_{field}`
/// entry per variant field) — the same shape a stage2 `-Ztrust-dump=mir:` of
/// `Result<(), std::io::Error>` produces.
fn variant_test_result_ty() -> Ty {
    Ty::Adt {
        arbitrary_precision: None,
        validity_wrapper: None,
        adt_kind: None,
        layout: None,
        name: "core::result::Result".to_string(),
        fields: vec![
            ("__tag".to_string(), Ty::i64()),
            ("__v0_0".to_string(), Ty::Unit),
            ("__v1_0".to_string(), variant_test_err_payload()),
        ]
        .into(),
        variants: vec![
            trust_types::VariantDef {
                name: "Ok".to_string(),
                discriminant: 0,
                fields: vec![("0".to_string(), Ty::Unit)],
            },
            trust_types::VariantDef {
                name: "Err".to_string(),
                discriminant: 1,
                fields: vec![("0".to_string(), variant_test_err_payload())],
            },
        ]
        .into(),
        disc_index_safe: false,
        faithful_enum_repr: None,
        enum_layout: None,
    }
}

/// One block that runs `stmts`, then drops local 1, then returns. `arg_count`
/// controls whether local 1 is an ARGUMENT (whose value no statement here
/// produces, so the tag can never be proved).
fn variant_drop_fn(drop_ty: Ty, arg_count: usize, stmts: Vec<Statement>) -> VerifiableFunction {
    VerifiableFunction {
        name: "variant_drop_fn".to_string(),
        def_path: "test::variant_drop_fn".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: drop_ty, name: Some("r".into()) },
                LocalDecl {
                    index: 2,
                    ty: Ty::Ref { mutable: true, inner: Box::new(Ty::Unit) },
                    name: Some("borrow".into()),
                },
                LocalDecl {
                    index: 3,
                    ty: variant_test_err_payload(),
                    name: Some("payload".into()),
                },
            ],
            blocks: vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts,
                    terminator: Terminator::Drop {
                        unwind: UnwindEdge::Unreachable,
                        place: Place::local(1),
                        target: BlockId(1),
                        span: SourceSpan::default(),
                    },
                },
                TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count,
            return_ty: Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    }
}

/// `_1 = Result::<_, _>::<variant>(..)` — a constant-variant aggregate write,
/// the shape a source-level `Ok(())` / `Err(e)` lowers to.
fn variant_const_write(variant: usize, operands: Vec<Operand>) -> Statement {
    Statement::Assign {
        place: Place::local(1),
        rvalue: Rvalue::Aggregate(
            AggregateKind::Adt {
                name: "core::result::Result".to_string(),
                variant,
                active_field: None,
                args: None,
            },
            operands,
        ),
        span: SourceSpan::default(),
    }
}

/// Descriptions of the per-variant drop-glue assumption rows on `module`.
fn drop_glue_variant_rows(module: &trust_ir::Module) -> Vec<String> {
    module
        .proof_obligations
        .iter()
        .filter(|o| {
            o.kind == trust_ir::ObligationKind::PanicFreedom
                && o.description.starts_with(trust_types::assumption::DROP_GLUE_ASSUMPTION_PREFIX)
        })
        .map(|o| o.description.clone())
        .collect()
}

#[test]
fn test_drop_glue_constant_ok_tag_does_not_charge_the_err_variant() {
    // THE PROBE. `let _r: Result<(), E> = Ok(());` writes a COMPILE-TIME
    // CONSTANT tag, so the `Err` arm of the drop-glue switch is dead code and
    // the `Ok` arm carries a unit payload with nothing to drop. Before the
    // variant lane this minted one blanket `[trust-drop-glue-assumption]` row
    // for the whole ADT; the drop now executes no code at all and is charged
    // nothing.
    let module = lower_to_trust_ir(&variant_drop_fn(
        variant_test_result_ty(),
        0,
        vec![variant_const_write(0, vec![Operand::Constant(ConstValue::Unit)])],
    ))
    .expect("constant-Ok drop must lower");
    assert_valid_module(&module);
    assert_eq!(
        drop_glue_variant_rows(&module),
        Vec::<String>::new(),
        "a provably-Ok tag with a unit payload must charge no drop-glue row"
    );
    assert_eq!(
        drop_glue_marker_count(&module),
        0,
        "no arm can panic, so no reachable-panic marker may be emitted"
    );
    let insts: Vec<_> = module.functions[0].blocks.iter().flat_map(|b| b.body.iter()).collect();
    assert!(
        insts.iter().any(|n| matches!(n.inst, Inst::Br { .. })),
        "the drop must still branch to its target"
    );
}

#[test]
fn test_drop_glue_constant_err_tag_still_charges_the_err_variant() {
    // The exclusion must be DIRECTIONAL, not a free pass: the same shape with a
    // constant `Err` tag proves the `Ok` arm dead and charges `Err`.
    let module = lower_to_trust_ir(&variant_drop_fn(
        variant_test_result_ty(),
        0,
        vec![variant_const_write(1, vec![Operand::Move(Place::local(3))])],
    ))
    .expect("constant-Err drop must lower");
    assert_valid_module(&module);
    let rows = drop_glue_variant_rows(&module);
    assert_eq!(rows.len(), 1, "the live `Err` arm must still be charged: {rows:?}");
    assert!(rows[0].contains("variant `Err`"), "the row must name the charged arm: {rows:?}");
    assert!(
        rows[0].contains("(#1) of `core::result::Result` has"),
        "the row must name the enum as Rust spells it: {rows:?}"
    );
    assert!(!rows[0].contains("Adt {"), "no Debug dump in the row: {rows:?}");
    assert!(
        rows[0].contains("[charged payload: (myapp::PanickyErr)]"),
        "the row must name the charged arm's payload types: {rows:?}"
    );
    assert!(rows[0].contains("Ok#0=excluded"), "the plan must record the exclusion: {rows:?}");
    assert_eq!(
        drop_glue_marker_count(&module),
        1,
        "a charged arm keeps its reachable-panic marker"
    );
}

#[test]
fn test_drop_glue_constant_tag_with_proved_payload_is_discharged_per_variant() {
    // `Result<PanickyErr, Bomb>` written `Ok(..)`: `Bomb` is not certified, so the
    // whole-ADT classifier fails, but the constant tag excludes `Err` and the live
    // `Ok` payload is a certified no-`Drop` struct. The drop is recorded as one
    // visible "discharged per variant" row, named as Rust spells the type.
    let ok_payload = variant_test_err_payload();
    let bomb = Ty::adt("myapp::Bomb", vec![("x".to_string(), Ty::i64())]);
    let result_ty = Ty::Adt {
        arbitrary_precision: None,
        validity_wrapper: None,
        adt_kind: None,
        layout: None,
        name: "core::result::Result".to_string(),
        fields: vec![
            ("__tag".to_string(), Ty::i64()),
            ("__v0_0".to_string(), ok_payload.clone()),
            ("__v1_0".to_string(), bomb.clone()),
        ]
        .into(),
        variants: vec![
            trust_types::VariantDef {
                name: "Ok".to_string(),
                discriminant: 0,
                fields: vec![("0".to_string(), ok_payload)],
            },
            trust_types::VariantDef {
                name: "Err".to_string(),
                discriminant: 1,
                fields: vec![("0".to_string(), bomb)],
            },
        ]
        .into(),
        disc_index_safe: false,
        faithful_enum_repr: None,
        enum_layout: None,
    };
    let structural_drop: std::collections::HashSet<String> =
        ["myapp::PanickyErr".to_string()].into_iter().collect();
    let module = lower_to_trust_ir_functions_with_context(
        "test_mod",
        &[variant_drop_fn(
            result_ty,
            0,
            vec![variant_const_write(0, vec![Operand::Move(Place::local(3))])],
        )],
        &std::collections::HashSet::new(),
        &structural_drop,
    )
    .expect("constant-Ok drop with a certified payload must lower");
    assert_valid_module(&module);
    assert_eq!(drop_glue_variant_rows(&module), Vec::<String>::new(), "nothing is charged");
    assert_eq!(drop_glue_marker_count(&module), 0, "no arm can panic");
    let rows: Vec<&str> = module
        .proof_obligations
        .iter()
        .filter(|o| o.kind == trust_ir::ObligationKind::PanicFreedom)
        .map(|o| o.description.as_str())
        .filter(|d| d.contains("discharged per variant"))
        .collect();
    assert_eq!(rows.len(), 1, "one visible discharge row: {rows:?}");
    assert!(
        rows[0].starts_with("drop glue for `core::result::Result` — discharged per variant"),
        "the row must name the Rust type: {rows:?}"
    );
    assert!(!rows[0].contains("Adt {"), "no Debug dump in the row: {rows:?}");
    assert!(
        rows[0].contains("Ok#0=proved-panic-free, Err#1=excluded"),
        "the plan must record the proved arm and the exclusion: {rows:?}"
    );
}

#[test]
fn test_drop_glue_unknown_tag_charges_only_the_droppable_variant() {
    // An ARGUMENT's tag is written outside this body, so nothing is proved and
    // every variant is live (fail-closed). `Ok`'s unit payload still needs no
    // obligation — the second, independent win — so exactly one row is charged,
    // matching today's blanket count for this shape.
    let module = lower_to_trust_ir(&variant_drop_fn(variant_test_result_ty(), 1, vec![]))
        .expect("argument drop must lower");
    assert_valid_module(&module);
    let rows = drop_glue_variant_rows(&module);
    assert_eq!(rows.len(), 1, "unknown tag must charge every undischargeable arm: {rows:?}");
    assert!(rows[0].contains("variant `Err`"));
    assert!(
        rows[0].contains("Ok#0=no-droppable-payload"),
        "the unit `Ok` payload runs no destructor: {rows:?}"
    );
}

#[test]
fn test_drop_glue_escaping_borrow_defeats_the_tag_proof() {
    // A `&mut` to the dropped local could rewrite the discriminant, so the
    // constant-Ok write no longer proves anything and the `Err` arm is charged.
    // Silence must never be reachable through an unmodelled write.
    let module = lower_to_trust_ir(&variant_drop_fn(
        variant_test_result_ty(),
        0,
        vec![
            variant_const_write(0, vec![Operand::Constant(ConstValue::Unit)]),
            Statement::Assign {
                place: Place::local(2),
                rvalue: Rvalue::Ref { mutable: true, place: Place::local(1) },
                span: SourceSpan::default(),
            },
        ],
    ))
    .expect("escaping-borrow drop must lower");
    assert_valid_module(&module);
    let rows = drop_glue_variant_rows(&module);
    assert_eq!(rows.len(), 1, "an escaping borrow must forfeit the exclusion: {rows:?}");
    assert!(rows[0].contains("variant `Err`"));
    assert!(
        !rows[0].contains("=excluded"),
        "no variant may be reported excluded once the local escapes: {rows:?}"
    );
}

#[test]
fn test_drop_glue_charges_one_row_per_undischargeable_variant() {
    // Attribution, not aggregation: a COMPILER-CERTIFIED no-`Drop` enum (in
    // `structural_drop`) with two independently-undischargeable payloads gets
    // two named rows where the blanket lane minted one. Each keeps its own
    // reachable-panic marker, so nothing is weakened — the charge is split, not
    // reduced.
    let enum_ty = Ty::Adt {
        arbitrary_precision: None,
        validity_wrapper: None,
        adt_kind: None,
        layout: None,
        name: "myapp::TwoBad".to_string(),
        fields: vec![
            ("__tag".to_string(), Ty::i64()),
            ("__v0_0".to_string(), variant_test_err_payload()),
            ("__v1_0".to_string(), Ty::adt("myapp::OtherErr", vec![("y".to_string(), Ty::i64())])),
        ]
        .into(),
        variants: vec![
            trust_types::VariantDef {
                name: "Left".to_string(),
                discriminant: 0,
                fields: vec![("0".to_string(), variant_test_err_payload())],
            },
            trust_types::VariantDef {
                name: "Right".to_string(),
                discriminant: 1,
                fields: vec![(
                    "0".to_string(),
                    Ty::adt("myapp::OtherErr", vec![("y".to_string(), Ty::i64())]),
                )],
            },
        ]
        .into(),
        disc_index_safe: false,
        faithful_enum_repr: None,
        enum_layout: None,
    };
    let structural_drop: std::collections::HashSet<String> =
        ["myapp::TwoBad".to_string()].into_iter().collect();
    let module = lower_to_trust_ir_functions_with_context(
        "test_mod",
        &[variant_drop_fn(enum_ty, 1, vec![])],
        &std::collections::HashSet::new(),
        &structural_drop,
    )
    .expect("two-bad-variant drop must lower");
    assert_valid_module(&module);
    let rows = drop_glue_variant_rows(&module);
    assert_eq!(rows.len(), 2, "each undischargeable arm gets its own row: {rows:?}");
    assert!(rows.iter().any(|r| r.contains("variant `Left`")));
    assert!(rows.iter().any(|r| r.contains("variant `Right`")));
    assert_eq!(
        drop_glue_marker_count(&module),
        2,
        "every charged arm keeps a reachable-panic marker"
    );
}

#[test]
fn test_drop_glue_unlicensed_user_enum_keeps_the_blanket_row() {
    // A user enum absent from `structural_drop` may carry its own `Drop` impl,
    // which would run on EVERY arm. The variant lane declines and the drop keeps
    // today's byte-identical blanket row even though the tag is a constant.
    let enum_ty = Ty::Adt {
        arbitrary_precision: None,
        validity_wrapper: None,
        adt_kind: None,
        layout: None,
        name: "myapp::MaybePanicky".to_string(),
        fields: vec![("__tag".to_string(), Ty::i64()), ("__v1_0".to_string(), Ty::i64())].into(),
        variants: vec![
            trust_types::VariantDef { name: "A".to_string(), discriminant: 0, fields: vec![] },
            trust_types::VariantDef {
                name: "B".to_string(),
                discriminant: 1,
                fields: vec![("0".to_string(), variant_test_err_payload())],
            },
        ]
        .into(),
        disc_index_safe: false,
        faithful_enum_repr: None,
        enum_layout: None,
    };
    let module = lower_to_trust_ir(&variant_drop_fn(
        enum_ty,
        0,
        vec![Statement::Assign {
            place: Place::local(1),
            rvalue: Rvalue::Aggregate(
                AggregateKind::Adt {
                    name: "myapp::MaybePanicky".to_string(),
                    variant: 0,
                    active_field: None,
                    args: None,
                },
                vec![],
            ),
            span: SourceSpan::default(),
        }],
    ))
    .expect("unlicensed enum drop must lower");
    assert_valid_module(&module);
    let rows = drop_glue_variant_rows(&module);
    assert_eq!(rows.len(), 1, "an unlicensed enum keeps one blanket row: {rows:?}");
    assert!(
        !rows[0].contains("variant `"),
        "the blanket row must not claim per-variant attribution: {rows:?}"
    );
}

#[test]
fn test_drop_glue_vec_of_plain_element_fails_closed_when_element_is_erased() {
    // A flattened `Vec` field tree does not authenticate its generic element or
    // allocator. A primitive-looking payload therefore cannot grant Drop authority.
    let vec_ty = Ty::Adt {
        adt_kind: None,
        layout: None,
        name: "alloc::vec::Vec".to_string(),
        fields: vec![("elem".to_string(), Ty::i64())].into(),
        variants: vec![].into(),
        disc_index_safe: false,
        faithful_enum_repr: None,
        enum_layout: None,
        arbitrary_precision: None,
        validity_wrapper: None,
    };
    let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(vec_ty)])
        .expect("Vec<i64> drop must lower");
    assert_valid_module(&module);

    assert!(
        has_drop_glue_marker(&module),
        "Vec<i64>'s erased generic lanes must keep the drop obligation"
    );
    assert_eq!(drop_glue_assumption_count(&module), 1);
    assert_eq!(drop_glue_discharged_count(&module), 0);
}

#[test]
fn test_drop_glue_kept_for_vec_of_user_drop_element() {
    // `Vec<PanickyGuard>` — the container itself is trusted, but its ELEMENT
    // carries a possible user `Drop`, so the whole must decline (never a false
    // proof from trusting the container alone).
    let guard_ty = Ty::adt("myapp::PanickyGuard", vec![("x".to_string(), Ty::i64())]);
    let vec_ty = Ty::Adt {
        adt_kind: None,
        layout: None,
        name: "alloc::vec::Vec".to_string(),
        fields: vec![("elem".to_string(), guard_ty)].into(),
        variants: vec![].into(),
        disc_index_safe: false,
        faithful_enum_repr: None,
        enum_layout: None,
        arbitrary_precision: None,
        validity_wrapper: None,
    };
    let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(vec_ty)])
        .expect("Vec<PanickyGuard> drop must lower fail-soft, not Err");
    assert_valid_module(&module);

    assert!(
        has_drop_glue_marker(&module),
        "Vec<PanickyGuard> must keep the Assert(false)+NoPanic marker (element may panic)"
    );
    assert_eq!(drop_glue_assumption_count(&module), 1);
}

#[test]
fn test_drop_glue_classifier_terminates_on_deep_recursive_type() {
    // Build a `Wrap0(Wrap1(Wrap2(...i64...)))` chain deeper than the classifier's
    // recursion fuel (`DROP_CLASSIFIER_FUEL` = 256 in `is_panic_free_drop_ext`),
    // simulating what a self-referential type would look like if the extractor's
    // Lever A (by-name `Ty::Datatype` back-reference) were somehow bypassed. The
    // classifier must TERMINATE — never stack-overflow or hang — and, since the
    // fuel runs out partway through, FAIL CLOSED rather than falsely prove.
    let mut inner = Ty::i64();
    let mut structural_drop = std::collections::HashSet::new();
    for depth in 0..300u32 {
        let name = format!("myapp::Wrap{depth}");
        structural_drop.insert(name.clone());
        inner = Ty::adt(name, vec![("0".to_string(), inner)]);
    }

    let module = lower_to_trust_ir_functions_with_context(
        "test_mod",
        &[drop_glue_test_fn(inner)],
        &std::collections::HashSet::new(),
        &structural_drop,
    )
    .expect("a deep (but finite) type chain must still lower — never hang");
    assert_valid_module(&module);

    assert_eq!(
        drop_glue_assumption_count(&module),
        1,
        "fuel-exhausted classification must fail closed to the drop-glue assumption row"
    );
}

#[test]
fn test_trait_object_drop_is_fatal_and_generic_param_drop_is_expected_absent() {
    // `Box<dyn MyTrait>` — a trait object's concrete drop glue is unknowable
    // (dynamic dispatch to whatever concrete type is behind the vtable).
    let boxed_dyn_ty = Ty::Adt {
        adt_kind: None,
        layout: None,
        name: "alloc::boxed::Box".to_string(),
        fields: vec![(
            "0".to_string(),
            Ty::Dynamic {
                trait_name: "myapp::MyTrait".to_string(),
                principal_key: Some("myapp::MyTrait".to_string()),
            },
        )]
        .into(),
        variants: vec![].into(),
        disc_index_safe: false,
        faithful_enum_repr: None,
        enum_layout: None,
        arbitrary_precision: None,
        validity_wrapper: None,
    };
    let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(boxed_dyn_ty)])
        .expect("Box<dyn Trait> drop must lower fail-soft, not Err");
    assert_valid_module(&module);
    assert!(has_drop_glue_marker(&module), "Box<dyn Trait> must keep the may-panic marker");
    assert_eq!(drop_glue_assumption_count(&module), 1);

    // An unresolved pre-monomorphization parameter is still opaque and therefore still
    // carries the reachable may-panic marker. Its boundary class is intentionally
    // EXPECTED-absent, however: the concrete Drop impl is selected and verified only at
    // monomorphization. This is an assumption, never a discharge or proof; strict policy
    // rejects it while explicit advisory policy may record it.
    let generic_ty = Ty::Unsupported {
        kind: "TyKind::Param".to_string(),
        detail: "generic type parameter T".to_string(),
    };
    let module2 = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(generic_ty)])
        .expect("generic-typed drop must lower fail-soft, not Err");
    assert_valid_module(&module2);
    assert!(has_drop_glue_marker(&module2), "an unresolved generic must keep the may-panic marker");
    assert_eq!(
        drop_glue_assumption_count(&module2),
        0,
        "a generic parameter is not a concrete user-Drop boundary"
    );
    assert_eq!(
        expected_absent_drop_count(&module2),
        1,
        "the generic parameter must remain visible as exactly one unproved expected-absent drop"
    );
}

// ---------------------------------------------------------------------------
// Build-5 drop-glue (Build-7 re-land): audited std-composed types (Ref/RefMut
// guards and num-bigint) prove panic-free; generic owning collections whose
// K/V types are erased from the compatibility IR and a user `Drop` anywhere in
// the visible field tree fail closed. Build-7 row-classification fix: a
// PROVEN drop records a named DISCHARGED row (never an unproved assumption
// row); a kept drop records the assumption row byte-identical to the base.
// See `is_total_drop_std_leaf` / `is_std_owning_or_scaffold`.
// ---------------------------------------------------------------------------

/// `std::ptr::NonNull<T>` — the pointer scaffold buried in owning containers.
fn ty_nonnull(pointee: Ty) -> Ty {
    Ty::adt(
        "std::ptr::NonNull",
        vec![("pointer".into(), Ty::RawPtr { mutable: false, pointee: Box::new(pointee) })],
    )
}
fn ty_phantomdata() -> Ty {
    Ty::adt("std::marker::PhantomData", vec![])
}
fn ty_global() -> Ty {
    Ty::adt("std::alloc::Global", vec![])
}

#[test]
fn test_build5_drop_glue_refmut_guard_is_leaf_and_proves() {
    // A `std::cell::RefMut` BORROW guard: it does NOT own/drop its referent — dropping it
    // only decrements a `Cell` borrow counter (the `BorrowRefMut` field's std `Drop`),
    // which is panic-free. To PROVE the classifier treats it as a non-owning LEAF (never
    // recursing into the referent), we give its `value` field a type that WOULD decline if
    // recursed — a user `PanickyGuard` with a possible panicking `Drop`. It must STILL
    // prove panic-free, because the guard genuinely never runs that `Drop`.
    let panicky = Ty::adt("my_crate::PanickyGuard", vec![("x".into(), Ty::i64())]);
    let refmut = Ty::adt(
        "std::cell::RefMut",
        vec![
            ("value".into(), ty_nonnull(panicky)),
            (
                "borrow".into(),
                Ty::adt(
                    "std::cell::BorrowRefMut",
                    vec![(
                        "borrow".into(),
                        Ty::Ref {
                            mutable: false,
                            inner: Box::new(Ty::adt(
                                "std::cell::Cell",
                                vec![("value".into(), Ty::i64())],
                            )),
                        },
                    )],
                ),
            ),
            ("marker".into(), ty_phantomdata()),
        ],
    );
    let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(refmut)])
        .expect("RefMut guard drop must lower");
    assert_valid_module(&module);
    assert!(
        !has_drop_glue_marker(&module),
        "a RefMut borrow guard never drops its referent — its drop is provably panic-free"
    );
    assert_eq!(drop_glue_assumption_count(&module), 0);
    assert_eq!(
        drop_glue_discharged_count(&module),
        1,
        "the proven drop must be recorded as ONE named discharged row"
    );
}

#[test]
fn test_build5_drop_glue_std_composed_arena_with_erased_maps_fails_closed() {
    // ny-cert's `Arena { values: Vec<BigRational>, dedup: HashMap<BigRational, u32> }` — a
    // user struct with NO `Drop` impl (in `structural_drop`) composed PURELY of std/num
    // fields. The `Vec` field is structurally visible, but the map K/V destructors are
    // not represented faithfully enough by the compatibility IR. The aggregate must
    // therefore fail closed even when its own no-`Drop` fact is certified.
    let arena = Ty::adt(
        "rational::Arena",
        vec![
            (
                "values".into(),
                // Vec<i64> stands in for Vec<BigRational> (element visible & panic-free).
                Ty::Adt {
                    adt_kind: None,
                    layout: None,
                    name: "alloc::vec::Vec".to_string(),
                    fields: vec![("elem".into(), Ty::i64())].into(),
                    variants: vec![].into(),
                    disc_index_safe: false,
                    faithful_enum_repr: None,
                    enum_layout: None,
                    arbitrary_precision: None,
                    validity_wrapper: None,
                },
            ),
            // HashMap whose K/V hashbrown erases. A visible safe-looking scaffold must
            // not turn the absent K/V evidence into a vacuous proof.
            (
                "dedup".into(),
                Ty::adt(
                    "std::collections::HashMap",
                    vec![(
                        "base".into(),
                        Ty::adt("my_crate::PanickyGuard", vec![("x".into(), Ty::i64())]),
                    )],
                ),
            ),
            // BTreeMap with a COMPACTED `root: Ty::Datatype{Option}` (the real oversized
            // shape) likewise lacks usable element evidence.
            (
                "ordered".into(),
                Ty::adt(
                    "std::collections::BTreeMap",
                    vec![(
                        "root".into(),
                        Ty::Datatype { name: "std::option::Option".into(), variants: vec![] },
                    )],
                ),
            ),
        ],
    );
    let structural_drop: std::collections::HashSet<String> =
        ["rational::Arena".to_string()].into_iter().collect();
    let module = lower_to_trust_ir_functions_with_context(
        "test_mod",
        &[drop_glue_test_fn(arena)],
        &std::collections::HashSet::new(),
        &structural_drop,
    )
    .expect("std-composed Arena drop must lower fail-soft");
    assert_valid_module(&module);
    assert_eq!(
        drop_glue_marker_count(&module),
        1,
        "an Arena containing element-erased maps must keep one may-panic marker"
    );
    assert_eq!(drop_glue_assumption_count(&module), 1);
    assert_eq!(drop_glue_discharged_count(&module), 0);
}

/// Build a drop-glue test type whose VISIBLE field evidence is insufficient (an
/// element-erased `HashMap`), parameterized by the extraction provenance stamp.
/// Only the stamp differs between the positive case and the controls.
fn root2_stamped_ty(name: &str, auth: Option<trust_types::AdtAuth>) -> Ty {
    Ty::Adt {
        name: name.to_string(),
        // An erased map: `is_element_erased_std_map_or_set` refuses this shape, and
        // the nested `PanickyGuard` would decline if anything recursed it. Neither
        // may matter — a `TotalDrop` stamp is a tcx-level certificate over the
        // CONCRETE owned tree, which is exactly the evidence this erased
        // compatibility IR cannot reconstruct.
        fields: vec![(
            "dedup".into(),
            Ty::adt(
                "std::collections::HashMap",
                vec![(
                    "base".into(),
                    Ty::adt("my_crate::PanickyGuard", vec![("x".into(), Ty::i64())]),
                )],
            ),
        )]
        .into(),
        variants: vec![].into(),
        disc_index_safe: false,
        faithful_enum_repr: None,
        enum_layout: None,
        adt_kind: None,
        layout: None,
        arbitrary_precision: auth,
        validity_wrapper: None,
    }
}

/// ROOT2 regression: the LIVE worklist `is_panic_free_drop_ext` must read the
/// `AdtAuth::TotalDrop` stamp.
///
/// The former recursive implementation (since deleted) carried this arm since
/// ROOT2 landed, but the worklist rewrite — the implementation the
/// `Terminator::Drop` arm actually calls — was written without it. The stamp was
/// therefore computed, authenticated, attached to the type, and read by NOBODY on
/// the live path: every drop-total ADT whose name matched none of the std arms fell
/// through to `_ => false` and minted a drop-glue assumption row. In the R50
/// ny-cert gate that was 30 of 33 drop-glue rows, including all four
/// `ny_cert::rational::RatError` rows.
///
/// The two controls are the soundness half and matter more than the positive: the
/// admission must be keyed on the STAMP, never on the name or the field shape.
#[test]
fn test_root2_total_drop_stamp_is_read_by_the_live_drop_classifier() {
    // POSITIVE — a user ADT (matching no std arm) carrying the ROOT2 stamp is
    // admitted FIELD-FREE.
    for name in ["ny_cert::rational::RatError", "some_crate::WrapperStruct"] {
        let ty = root2_stamped_ty(name, Some(trust_types::AdtAuth::TotalDrop(None)));
        let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(ty)])
            .expect("a TotalDrop-stamped drop must lower");
        assert_valid_module(&module);
        assert_eq!(
            drop_glue_assumption_count(&module),
            0,
            "{name}: the extraction-certified TotalDrop stamp must discharge the drop"
        );
        assert_eq!(
            drop_glue_discharged_count(&module),
            1,
            "{name}: the discharge must be recorded as ONE visible named row"
        );
    }

    // ORDERING CONTROL — a `TotalDrop`-stamped std map. The element-erased map/set
    // gate name-matches `collections` and would pre-empt the stamp if this arm were
    // placed after it, so this pins the arm's position, not just its existence.
    let map = root2_stamped_ty(
        "std::collections::BTreeMap",
        Some(trust_types::AdtAuth::TotalDrop(Some(trust_types::TotalMapKind::OrdGlobal))),
    );
    let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(map)])
        .expect("a stamped map drop must lower");
    assert_eq!(
        drop_glue_assumption_count(&module),
        0,
        "the TotalDrop arm must precede the element-erased map/set gate"
    );

    // FAIL-CLOSED CONTROL 1 (the serde(skip) direction) — the SAME type with no
    // stamp must still be charged. The carrier field is `#[serde(skip)]` in both
    // directions, so every decoded/shadow bundle reads `None` and lands here: a
    // stamp can never be forged over the wire.
    let unstamped = root2_stamped_ty("ny_cert::rational::RatError", None);
    let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(unstamped)])
        .expect("an unstamped drop must lower fail-soft");
    assert_valid_module(&module);
    assert_eq!(
        drop_glue_assumption_count(&module),
        1,
        "without the stamp the identical type must keep its may-panic marker — the \
         admission is keyed on the stamp, never on the name or field shape"
    );
    assert_eq!(drop_glue_discharged_count(&module), 0);

    // FAIL-CLOSED CONTROL 2 (the C2 reservation) — a plain `TotalStdMap` is
    // key-total but says NOTHING about whether its value `V` owns a panicking
    // `Drop`. It must NOT be admitted field-free.
    let key_total = root2_stamped_ty(
        "std::collections::BTreeMap",
        Some(trust_types::AdtAuth::TotalStdMap(trust_types::TotalMapKind::OrdGlobal)),
    );
    let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(key_total)])
        .expect("a key-total map drop must lower fail-soft");
    assert_eq!(
        drop_glue_assumption_count(&module),
        1,
        "TotalStdMap certifies the KEY, not the value's drop — it must stay charged"
    );
}

#[test]
fn test_drop_glue_accepts_only_exact_pthread_mutex_and_condvar_leaves() {
    for name in
        ["std::sys::sync::mutex::pthread::Mutex", "std::sys::sync::condvar::pthread::Condvar"]
    {
        for (shape_name, shape) in [
            ("adt", Ty::adt(name, vec![])),
            ("datatype", Ty::Datatype { name: name.into(), variants: vec![] }),
        ] {
            let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(shape)])
                .unwrap_or_else(|error| {
                    panic!("exact pthread {shape_name} leaf `{name}` must lower: {error:?}")
                });
            assert_valid_module(&module);
            assert_eq!(
                drop_glue_marker_count(&module),
                0,
                "exact {shape_name} leaf `{name}` must prove"
            );
            assert_eq!(drop_glue_assumption_count(&module), 0);
            assert_eq!(drop_glue_discharged_count(&module), 1);
        }
    }

    for name in [
        "std::sys::sync::once_box::OnceBox",
        "std::sys::sync::mutex::futex::Mutex",
        "std::sys::sync::condvar::futex::Condvar",
        "std::sys::sync::lookalike::Mutex",
        "std::sys::sync::mutex::pthread::MutexGuard",
    ] {
        for (shape_name, shape) in [
            ("adt", Ty::adt(name, vec![])),
            ("datatype", Ty::Datatype { name: name.into(), variants: vec![] }),
        ] {
            let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(shape)])
                .unwrap_or_else(|error| {
                    panic!("near-miss {shape_name} sync type `{name}` must lower: {error:?}")
                });
            assert_valid_module(&module);
            assert_eq!(
                drop_glue_marker_count(&module),
                1,
                "near-miss {shape_name} sync type `{name}` must fail closed"
            );
            assert_eq!(drop_glue_assumption_count(&module), 1);
            assert_eq!(drop_glue_discharged_count(&module), 0);
        }
    }
}

#[test]
fn test_drop_glue_map_set_families_fail_closed_for_erased_compacted_and_forged_shapes() {
    let names = [
        "std::collections::hash::map::HashMap",
        "std::collections::hash::set::HashSet",
        "alloc::collections::btree::map::BTreeMap",
        "alloc::collections::btree::set::BTreeSet",
        "std::collections::HashMap",
        "std::collections::HashSet",
        "std::collections::BTreeMap",
        "std::collections::BTreeSet",
    ];

    for name in names {
        let shapes = [
            Ty::adt(name, vec![]),
            Ty::adt(
                name,
                vec![("ctrl".into(), Ty::RawPtr { mutable: false, pointee: Box::new(Ty::u8()) })],
            ),
            Ty::Datatype { name: name.into(), variants: vec![] },
        ];
        // Even a forged compiler context that claims the collection itself has no
        // explicit `Drop` impl cannot recover its erased K/V destructor evidence.
        let structural_drop = std::collections::HashSet::from([name.to_string()]);
        for shape in shapes {
            let module = lower_to_trust_ir_functions_with_context(
                "test_mod",
                &[drop_glue_test_fn(shape)],
                &std::collections::HashSet::new(),
                &structural_drop,
            )
            .unwrap_or_else(|error| panic!("map/set shape `{name}` must lower: {error:?}"));
            assert_valid_module(&module);
            assert_eq!(
                drop_glue_marker_count(&module),
                1,
                "map/set shape `{name}` must keep exactly one may-panic marker"
            );
            assert_eq!(drop_glue_assumption_count(&module), 1);
            assert_eq!(drop_glue_discharged_count(&module), 0);
        }
    }

    // `Box<T, A>` and `RawVec<T, A>` may likewise reach this compatibility
    // surface without their allocator parameter.  A primitive-looking pointer
    // field cannot prove that the erased allocator's destructor is panic-free.
    for (label, shape) in [
        (
            "Box with erased allocator",
            Ty::adt(
                "alloc::boxed::Box",
                vec![("ptr".into(), Ty::RawPtr { mutable: false, pointee: Box::new(Ty::i64()) })],
            ),
        ),
        (
            "RawVec with erased allocator",
            Ty::adt(
                "alloc::raw_vec::RawVec",
                vec![("ptr".into(), Ty::RawPtr { mutable: false, pointee: Box::new(Ty::i64()) })],
            ),
        ),
    ] {
        let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(shape)])
            .unwrap_or_else(|error| panic!("{label} must lower: {error:?}"));
        assert_valid_module(&module);
        assert_eq!(drop_glue_marker_count(&module), 1, "{label} must fail closed");
        assert_eq!(drop_glue_assumption_count(&module), 1);
        assert_eq!(drop_glue_discharged_count(&module), 0);
    }
}

#[test]
fn test_build5_drop_glue_vec_intoiter_fails_closed_and_bigint_proves() {
    // The compatibility type cannot authenticate every element/allocator lane of
    // `Vec::IntoIter<T>`. Even a primitive-looking field tree therefore keeps the
    // drop obligation.
    let into_iter = Ty::adt(
        "std::vec::IntoIter",
        vec![
            ("ptr".into(), ty_nonnull(Ty::i64())),
            ("end".into(), Ty::RawPtr { mutable: false, pointee: Box::new(Ty::i64()) }),
            ("cap".into(), Ty::u64()),
            ("alloc".into(), ty_global()),
            ("phantom".into(), ty_phantomdata()),
        ],
    );
    let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(into_iter)])
        .expect("Vec::IntoIter<i64> drop must lower");
    assert_valid_module(&module);
    assert!(has_drop_glue_marker(&module), "Vec::IntoIter<i64> drop must fail closed");
    assert_eq!(drop_glue_assumption_count(&module), 1);
    assert_eq!(drop_glue_discharged_count(&module), 0);

    // A printable third-party path is not authenticated crate/destructor
    // provenance; both full and compacted spellings fail closed.
    for bigint in [
        Ty::adt("num_bigint::BigInt", vec![("data".into(), Ty::u64())]),
        Ty::Datatype { name: "num_bigint::BigInt".into(), variants: vec![] },
    ] {
        let module = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(bigint)])
            .expect("BigInt drop must lower");
        assert_valid_module(&module);
        assert!(has_drop_glue_marker(&module), "unauthenticated BigInt drop must fail closed");
        assert_eq!(drop_glue_assumption_count(&module), 1);
        assert_eq!(drop_glue_discharged_count(&module), 0);
    }
}

#[test]
fn test_build5_drop_glue_fails_closed_on_user_drop_in_field_tree() {
    // SOUNDNESS: the Build-5 additions must NOT weaken the fail-closed default. A user
    // struct (no `Drop`, in `structural_drop`) that OWNS a field whose type carries a
    // possible user `Drop` (a `PanickyGuard`, NOT a leaf/scaffold, NOT in structural_drop)
    // must KEEP its drop-glue assumption row — the element recursion reaches the panicky
    // field and declines.
    let panicky = Ty::adt("my_crate::PanickyGuard", vec![("x".into(), Ty::i64())]);
    let composed = Ty::adt(
        "myapp::Composed",
        vec![
            ("values".into(), Ty::adt("alloc::vec::Vec", vec![("elem".into(), Ty::i64())])),
            // An OWNED user-Drop field (directly held, not behind a borrow guard).
            ("guard".into(), panicky.clone()),
        ],
    );
    let structural_drop: std::collections::HashSet<String> =
        ["myapp::Composed".to_string()].into_iter().collect();
    let module = lower_to_trust_ir_functions_with_context(
        "test_mod",
        &[drop_glue_test_fn(composed)],
        &std::collections::HashSet::new(),
        &structural_drop,
    )
    .expect("must lower fail-soft, not Err");
    assert_valid_module(&module);
    assert!(
        has_drop_glue_marker(&module),
        "a user Drop reachable in the owned field tree must keep the may-panic marker"
    );
    assert_eq!(drop_glue_assumption_count(&module), 1);
    assert_eq!(
        drop_glue_discharged_count(&module),
        0,
        "an UNPROVEN drop must never mint a discharged row"
    );

    // A directly-dropped `Vec<PanickyGuard>` via the new IntoIter path likewise declines
    // (element visible through the pointer scaffold).
    let into_iter_panicky = Ty::adt(
        "std::vec::IntoIter",
        vec![
            ("ptr".into(), ty_nonnull(panicky)),
            ("cap".into(), Ty::u64()),
            ("alloc".into(), ty_global()),
            ("phantom".into(), ty_phantomdata()),
        ],
    );
    let module2 = lower_to_trust_ir_functions("test_mod", &[drop_glue_test_fn(into_iter_panicky)])
        .expect("must lower fail-soft");
    assert_valid_module(&module2);
    assert!(
        has_drop_glue_marker(&module2),
        "Vec::IntoIter<PanickyGuard> must decline (element drop reachable via ptr)"
    );
    assert_eq!(drop_glue_assumption_count(&module2), 1);
    assert_eq!(drop_glue_discharged_count(&module2), 0);
}

// ---------------------------------------------------------------------------
// Round-5 gating extension: closure-environment drop glue (captures-only) and
// the element-gated `num_rational::Ratio` leaf. Clears the 27 assumption rows
// at rational.rs `intern::{closure#0}` (drop of the closure capturing a
// full-field `Ratio<BigInt>`). Fail-closed: `Ratio<UserAdt>` and an
// element-less compacted `Ratio` keep their rows.
// ---------------------------------------------------------------------------

/// A full-field `num_rational::Ratio<num_bigint::BigInt>` shaped exactly like the
/// real extractor output in the batch-49 census rows (`sign` enum + `data`
/// BigUint/Vec tree). The classifier accepts `BigInt` as a by-name LEAF, so the
/// foreign `Sign` enum inside (which would DECLINE if recursed) also proves the
/// leaf short-circuit is what fires.
fn ty_ratio_bigint_full() -> Ty {
    let sign = Ty::Adt {
        adt_kind: None,
        layout: None,
        name: "num_bigint::Sign".to_string(),
        fields: vec![("__tag".to_string(), Ty::i64())].into(),
        variants: vec![
            trust_types::VariantDef { name: "Minus".to_string(), discriminant: 0, fields: vec![] },
            trust_types::VariantDef { name: "NoSign".to_string(), discriminant: 1, fields: vec![] },
            trust_types::VariantDef { name: "Plus".to_string(), discriminant: 2, fields: vec![] },
        ]
        .into(),
        disc_index_safe: true,
        faithful_enum_repr: None,
        enum_layout: None,
        arbitrary_precision: None,
        validity_wrapper: None,
    };
    let biguint = Ty::adt(
        "num_bigint::BigUint",
        vec![("data".to_string(), Ty::adt("std::vec::Vec", vec![("len".to_string(), Ty::u64())]))],
    );
    let bigint = Ty::adt(
        "num_bigint::BigInt",
        vec![("sign".to_string(), sign), ("data".to_string(), biguint)],
    );
    Ty::adt(
        "num_rational::Ratio",
        vec![("numer".to_string(), bigint.clone()), ("denom".to_string(), bigint)],
    )
}

/// The `intern::{closure#0}`-shaped closure environment: one capture of `upvar`.
fn ty_intern_closure(upvar: Ty) -> Ty {
    Ty::Closure {
        name: "rational::intern::{closure#0}".to_string(),
        upvars: vec![upvar],
        call: None,
    }
}

#[test]
fn test_round5_drop_glue_closure_capturing_ratio_bigint_proves() {
    // The exact census shape still lacks authenticated external destructor
    // identity, so structural_drop EMPTY means it must fail closed.
    let module = lower_to_trust_ir_functions(
        "test_mod",
        &[drop_glue_test_fn(ty_intern_closure(ty_ratio_bigint_full()))],
    )
    .expect("closure-capture Ratio<BigInt> drop must lower");
    assert_valid_module(&module);
    assert!(has_drop_glue_marker(&module), "unauthenticated Ratio<BigInt> drop fails closed");
    assert_eq!(drop_glue_assumption_count(&module), 1);
    assert_eq!(drop_glue_discharged_count(&module), 0);

    // The `Ty::Datatype` spelling of `Ratio` with VISIBLE, all-total element
    // fields likewise proves (same gate, other spelling).
    let bigint_leaf = Ty::Datatype { name: "num_bigint::BigInt".to_string(), variants: vec![] };
    let ratio_datatype = Ty::Datatype {
        name: "num_rational::Ratio".to_string(),
        variants: vec![(
            "Ratio".to_string(),
            vec![("numer".to_string(), bigint_leaf.clone()), ("denom".to_string(), bigint_leaf)],
        )],
    };
    let module2 = lower_to_trust_ir_functions(
        "test_mod",
        &[drop_glue_test_fn(ty_intern_closure(ratio_datatype))],
    )
    .expect("visible-field Ratio datatype drop must lower");
    assert_valid_module(&module2);
    assert!(has_drop_glue_marker(&module2));
    assert_eq!(drop_glue_assumption_count(&module2), 1);
    assert_eq!(drop_glue_discharged_count(&module2), 0);
}

#[test]
fn test_round5_drop_glue_closure_capturing_ratio_of_user_adt_fails_closed() {
    // SOUNDNESS KEYSTONE: `Ratio` is generic — `Ratio<UserType>` may own a
    // panicking user `Drop`, so the element gate must DECLINE it. The closure
    // arm's recursion reaches the user field and keeps the assumption row.
    let panicky = Ty::adt("my_crate::PanickyGuard", vec![("x".to_string(), Ty::i64())]);
    let ratio_user = Ty::adt(
        "num_rational::Ratio",
        vec![("numer".to_string(), panicky.clone()), ("denom".to_string(), panicky)],
    );
    let module = lower_to_trust_ir_functions(
        "test_mod",
        &[drop_glue_test_fn(ty_intern_closure(ratio_user))],
    )
    .expect("must lower fail-soft, not Err");
    assert_valid_module(&module);
    assert!(
        has_drop_glue_marker(&module),
        "Ratio<UserAdt> must keep the may-panic marker (user Drop reachable via element)"
    );
    assert_eq!(drop_glue_assumption_count(&module), 1);
    assert_eq!(drop_glue_discharged_count(&module), 0);
}

#[test]
fn test_round5_drop_glue_closure_capturing_compacted_ratio_fails_closed() {
    // A by-name COMPACTED `Ratio` back-reference (`variants: []` — the
    // `compact_oversized_field` shape) has NO visible element: it could be
    // `Ratio<UserPanickyDrop>`, so name-only trust is forbidden and the row is
    // KEPT. Same for a degenerate ctor list with zero visible fields, and for
    // an element-less `Ty::Adt` spelling.
    for compacted in [
        Ty::Datatype { name: "num_rational::Ratio".to_string(), variants: vec![] },
        Ty::Datatype {
            name: "num_rational::Ratio".to_string(),
            variants: vec![("Ratio".to_string(), vec![])],
        },
        Ty::adt("num_rational::Ratio", vec![]),
    ] {
        let module = lower_to_trust_ir_functions(
            "test_mod",
            &[drop_glue_test_fn(ty_intern_closure(compacted))],
        )
        .expect("must lower fail-soft, not Err");
        assert_valid_module(&module);
        assert!(
            has_drop_glue_marker(&module),
            "an element-less Ratio must keep the may-panic marker (never name-only trusted)"
        );
        assert_eq!(drop_glue_assumption_count(&module), 1);
        assert_eq!(drop_glue_discharged_count(&module), 0);
    }
}

#[test]
fn test_lower_unresolved_call_fails_soft_with_honest_panic_obligation() {
    let func = VerifiableFunction {
        name: "caller".to_string(),
        def_path: "test::caller".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![LocalDecl { index: 0, ty: Ty::i32(), name: None }],
            blocks: vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Call {
                        unwind: UnwindEdge::Unreachable,
                        is_unsafe_sig: false,
                        callee_identity: None,
                        callee_key: None,
                        is_foreign: false,
                        func: "callee".to_string(),
                        args: vec![Operand::Constant(ConstValue::Int(10))],
                        dest: Place::local(0),
                        target: Some(BlockId(1)),
                        span: SourceSpan::default(),
                        atomic: None,
                    },
                },
                TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 0,
            return_ty: Ty::i32(),
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };

    // FAIL-SOFT (was fail-closed-by-Err): an unresolved call no longer fails
    // the whole lowering — it lowers to the audited may-panic encoding
    // (Assert(false)+NoPanic marker + havoc result + ONE marked PanicFreedom
    // obligation), so the function's OTHER obligations get real verdicts while
    // panic-freedom through this call site stays honestly unprovable. The
    // fail-CLOSED property this test protects is unchanged: the call can never
    // be silently treated as panic-free or lowered to a phantom Call.
    let module = lower_to_trust_ir(&func).expect("unresolved call must lower fail-soft, not Err");
    assert_valid_module(&module);
    let insts: Vec<_> = module.functions[0].blocks.iter().flat_map(|b| b.body.iter()).collect();
    assert!(
        insts.iter().any(|n| {
            matches!(n.inst, Inst::Assert { .. })
                && n.proofs.contains(&trust_ir::ProofAnnotation::NoPanic)
        }),
        "expected the Assert(false)+NoPanic may-panic marker"
    );
    assert!(
        !insts.iter().any(|n| matches!(n.inst, Inst::Call { .. })),
        "an unresolved callee must not lower to a phantom Call"
    );
    assert_eq!(
        module
            .proof_obligations
            .iter()
            .filter(|o| {
                o.kind == trust_ir::ObligationKind::PanicFreedom
                    && o.description
                        .starts_with(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
            })
            .count(),
        1,
        "expected exactly one marked PanicFreedom obligation"
    );
}

#[test]
fn test_panic_call_lowers_to_panic_freedom_obligation() {
    // A user `assert!`/`panic!` lowers to a diverging Call to a panic intrinsic
    // that is never part of the user crate's module. It must lower as a
    // panic-freedom obligation (prove the site unreachable), not fail closed.
    let func = VerifiableFunction {
        name: "panics".to_string(),
        def_path: "test::panics".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![LocalDecl { index: 0, ty: Ty::Unit, name: None }],
            blocks: vec![TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: Terminator::Call {
                    unwind: UnwindEdge::Unreachable,
                    is_unsafe_sig: false,
                    callee_identity: None,
                    // DIVERGE-ANCHOR-1 / DIVERGE-ENTRY-1: the key the extractor mints for
                    // core's own `panicking::panic`, `diverging_entry` stamped; the site
                    // encoding requires the stamp.
                    callee_key: Some(crate::diverging_site_anchor_tests::entry_key_for(
                        "core",
                        "core::panicking::panic",
                    )),
                    is_foreign: false,
                    func: "core::panicking::panic".to_string(),
                    args: vec![],
                    dest: Place::local(0),
                    target: None,
                    span: SourceSpan::default(),
                    atomic: None,
                },
            }],
            arg_count: 0,
            return_ty: Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };

    let module = lower_to_trust_ir(&func).expect("panic call must lower, not fail closed");
    let has_panic_freedom = module.proof_obligations.iter().any(|po| {
        matches!(po.kind, trust_ir::proof::ObligationKind::PanicFreedom)
            && po.description.contains("must be unreachable")
    });
    assert!(has_panic_freedom, "panic call should yield a PanicFreedom obligation");
}

// R139 COUPLING PIN — the bridge (charging) half of the asserted niche-wrap
// landed FIRST, per the R107 ordering. This pin is what forbids the extractor
// admission ever going live without the charge: a usize -> UsizeNoHighBit cast
// (the post-admission spelling convert.rs will emit) must lower WITH the
// range assert `src <= isize::MAX as usize` feeding an Inst::Assert. If the
// bridge guard ever mismatches the admitted spelling, this pin — not the
// gate — goes red.
#[test]
fn usize_to_no_high_bit_wrap_cast_charges_the_range_assert() {
    let wrapper = Ty::Adt {
        adt_kind: None,
        layout: None,
        name: "core::num::niche_types::UsizeNoHighBit".into(),
        fields: vec![("0".into(), Ty::usize())].into(),
        variants: vec![].into(),
        disc_index_safe: true,
        faithful_enum_repr: None,
        enum_layout: None,
        arbitrary_precision: None,
        validity_wrapper: None,
    };
    let func = VerifiableFunction {
        name: "no_high_bit_wrap".into(),
        def_path: "test::no_high_bit_wrap".into(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: Ty::usize(), name: Some("raw".into()) },
                LocalDecl { index: 2, ty: wrapper.clone(), name: Some("wrapped".into()) },
            ],
            blocks: vec![TrustBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(2),
                    rvalue: Rvalue::Cast(Operand::Copy(Place::local(1)), wrapper),
                    span: SourceSpan::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };
    let module = lower_to_trust_ir(&func).expect("the charged niche-wrap cast should lower");
    assert_valid_module(&module);
    let body: Vec<_> = module.functions[0].blocks.iter().flat_map(|b| b.body.iter()).collect();
    // The bound constant, the Ule compare on it, and the Assert consuming it.
    let bound_consts: Vec<ValueId> = body
        .iter()
        .filter_map(|node| match (&node.inst, node.results.as_slice()) {
            (Inst::Const { value, .. }, [r])
                if format!("{value:?}").contains("9223372036854775807") =>
            {
                Some(*r)
            }
            _ => None,
        })
        .collect();
    assert!(!bound_consts.is_empty(), "the isize::MAX bound constant must be emitted");
    let cmp_results: Vec<ValueId> = body
        .iter()
        .filter_map(|node| match (&node.inst, node.results.as_slice()) {
            (Inst::ICmp { op: ICmpOp::Ule, rhs, .. }, [r]) if bound_consts.contains(rhs) => {
                Some(*r)
            }
            _ => None,
        })
        .collect();
    assert!(!cmp_results.is_empty(), "the src <= isize::MAX compare must be emitted");
    assert!(
        body.iter().any(
            |node| matches!(&node.inst, Inst::Assert { cond, .. } if cmp_results.contains(cond))
        ),
        "the range compare must feed an Inst::Assert (the CHARGE)"
    );
}

// R128: the enum-wrap membership set comes from the TARGET'S OWN declared
// discriminants — a forged `{1,2,3}` enum is charged `src ∈ {1,2,3}`, never a
// power-of-two formula (the under-charge false proof the helper's doc names:
// 4 passes pow2 but is invalid for `{1,2,3}`). Payload-bearing variants and
// multi-payload wrappers fail closed.
#[test]
fn enum_wrap_membership_set_is_the_targets_own_declared_discriminants() {
    use trust_types::VariantDef;
    let fieldless = |name: &str, d: i128| VariantDef {
        name: name.to_string(),
        discriminant: d,
        fields: vec![],
    };
    let forged =
        Ty::adt_enum("user::Forged", vec![fieldless("A", 1), fieldless("B", 2), fieldless("C", 3)]);
    let defs = trust_types::DatatypeDefs::default();
    assert_eq!(
        super::lower::fieldless_enum_wrap_discriminants(&defs, &forged),
        Some(vec![1, 2, 3]),
        "the charge must be the enum's OWN set"
    );
    // The Alignment shape: transparent struct over the enum — chased.
    let wrapper = Ty::adt("user::Wrap", vec![("0".to_string(), forged.clone())]);
    assert_eq!(
        super::lower::fieldless_enum_wrap_discriminants(&defs, &wrapper),
        Some(vec![1, 2, 3])
    );
    // Payload-bearing variant: fail closed.
    let payload = Ty::adt_enum(
        "user::Payload",
        vec![
            fieldless("A", 1),
            VariantDef {
                name: "B".to_string(),
                discriminant: 2,
                fields: vec![("0".to_string(), Ty::u64())],
            },
        ],
    );
    assert_eq!(super::lower::fieldless_enum_wrap_discriminants(&defs, &payload), None);
    // Two-field struct: not the transparent shape — fail closed.
    let two = Ty::adt("user::Two", vec![("0".to_string(), forged), ("1".to_string(), Ty::u64())]);
    assert_eq!(super::lower::fieldless_enum_wrap_discriminants(&defs, &two), None);
}

// R149 REGRESSION PIN — the membership-assert constants must be typed BY THE
// COMPARE TYPE, not by the magnitude of the discriminant.
//
// `emit_const` defaults `ConstValue::Int` to `I64`, and widens to `I128` for a
// value that does not fit `i64` (see the arm's own comment). An UNSIGNED source
// — `usize -> core::mem::Alignment`, inlined into every bundled Layout/RawVec
// member — therefore used to compare `icmp ty=U64` against `I64` constants, and
// against an `I128` one for the `1 << 63` discriminant. That is an ill-typed
// module: the validator rejects it wholesale, which strips native proof
// authority from EVERY obligation in the bundle, not just this function's.
//
// This pin is what makes that regression LOUD. The fix (`134c5b9264`) landed
// with no test, and the failure it prevents is invisible from the verdict side:
// the module simply stops being a valid solve input, and every row reads
// `unsupported` for a reason that names the icmp and not the cast that built it.
//
// The `1 << 63` discriminant is deliberately present — it is the ONLY one that
// exercises the `I128` widening leg, and a fix that typed the small constants
// correctly while leaving that leg alone would still produce an invalid module.
#[test]
fn unsigned_enum_wrap_membership_constants_are_typed_by_the_compare_type() {
    // The `core::mem::Alignment` shape: a fieldless enum whose discriminants are
    // powers of two, up to and including the one that overflows `i64`.
    let variants: Vec<VariantDef> = (0..64u32)
        .map(|shift| VariantDef {
            name: format!("_Align1Shl{shift}"),
            discriminant: 1i128 << shift,
            fields: vec![],
        })
        .collect();
    let align_enum = Ty::adt_enum("core::mem::alignment::Alignment", variants);

    let func = VerifiableFunction {
        name: "align_wrap".into(),
        def_path: "test::align_wrap".into(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: Ty::usize(), name: Some("raw".into()) },
                LocalDecl { index: 2, ty: align_enum.clone(), name: Some("aligned".into()) },
            ],
            blocks: vec![TrustBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(2),
                    rvalue: Rvalue::Cast(Operand::Copy(Place::local(1)), align_enum),
                    span: SourceSpan::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };

    let module = lower_to_trust_ir(&func).expect("the enum-wrap cast should lower");
    // The headline: an ill-typed icmp makes this fail, and with it every
    // obligation the bundle carries.
    assert_valid_module(&module);

    let body: Vec<_> = module.functions[0].blocks.iter().flat_map(|b| b.body.iter()).collect();
    // Map each emitted constant to the type it was emitted AT.
    let const_ty: std::collections::HashMap<ValueId, TrustIrTy> = body
        .iter()
        .filter_map(|node| match (&node.inst, node.results.as_slice()) {
            (Inst::Const { ty, .. }, [r]) => Some((*r, ty.clone())),
            _ => None,
        })
        .collect();

    let membership: Vec<(&TrustIrTy, &TrustIrTy)> = body
        .iter()
        .filter_map(|node| match &node.inst {
            Inst::ICmp { op: ICmpOp::Eq, ty, rhs, .. } => {
                const_ty.get(rhs).map(|rhs_ty| (ty, rhs_ty))
            }
            _ => None,
        })
        .collect();
    assert_eq!(membership.len(), 64, "every declared discriminant owes one membership compare");
    for (cmp_ty, rhs_ty) in membership {
        assert_eq!(
            cmp_ty,
            &TrustIrTy::U64,
            "an unsigned source must compare at the unsigned width"
        );
        assert_eq!(
            rhs_ty, cmp_ty,
            "the membership constant must carry the COMPARE type, not a \
             magnitude-inferred signed one (I64, or I128 for `1 << 63`)"
        );
    }
}

// R177: a DIVERGING site (`target: None`) of a std panic/abort TERMINAL
// (`raw_vec::handle_error`, `unwrap_failed`, `handle_alloc_error`,
// `process::abort`, …) takes the same must-be-unreachable charge as
// `core::panicking::*` — that is what lets the RawVec/unwrap-bearing std
// bodies LOWER instead of failing at the Opaque bail and cascading their
// callers out of the bundle. A RETURNING call to a fn that merely SHARES the
// tail must NOT take the arm: this arm ends the block in `Unreachable`, and
// erasing a live continuation would erase that continuation's obligations.
#[test]
fn diverging_terminal_charges_reachability_and_returning_same_tail_does_not() {
    // DIVERGE-ANCHOR-1 / DIVERGE-ENTRY-1: each sysroot callee below carries the key the
    // extractor mints for that real entry (its defining crate, `diverging_entry`
    // stamped, whatever the site); `my_crate` carries a non-sysroot key.
    let key_for = |callee: &str| {
        let krate = callee.split("::").next().unwrap_or_default();
        if matches!(krate, "core" | "alloc" | "std") {
            crate::diverging_site_anchor_tests::entry_key_for(krate, callee)
        } else {
            crate::diverging_site_anchor_tests::non_sysroot_callee_key(krate)
        }
    };
    let mk = |callee: &str, target: Option<BlockId>| {
        let mut blocks = vec![TrustBlock {
            id: BlockId(0),
            stmts: vec![],
            terminator: Terminator::Call {
                unwind: UnwindEdge::Unreachable,
                is_unsafe_sig: false,
                callee_identity: None,
                callee_key: Some(key_for(callee)),
                is_foreign: false,
                func: callee.to_string(),
                args: vec![],
                dest: Place::local(0),
                target,
                span: SourceSpan::default(),
                atomic: None,
            },
        }];
        if target.is_some() {
            blocks.push(TrustBlock {
                id: BlockId(1),
                stmts: vec![],
                terminator: Terminator::Return,
            });
        }
        VerifiableFunction {
            name: "terminal_site".to_string(),
            def_path: "test::terminal_site".to_string(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals: vec![LocalDecl { index: 0, ty: Ty::Unit, name: None }],
                blocks,
                arg_count: 0,
                return_ty: Ty::Unit,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    };

    for callee in [
        "alloc::raw_vec::handle_error",
        "alloc::raw_vec::capacity_overflow",
        "alloc::alloc::handle_alloc_error",
        "core::option::unwrap_failed",
        "core::result::unwrap_failed",
        "std::process::abort",
    ] {
        let module = lower_to_trust_ir(&mk(callee, None))
            .unwrap_or_else(|e| panic!("diverging terminal `{callee}` must lower: {e:?}"));
        let charged = module.proof_obligations.iter().any(|po| {
            matches!(po.kind, trust_ir::proof::ObligationKind::PanicFreedom)
                && po.description.contains("must be unreachable")
                && po.description.contains(callee)
        });
        assert!(charged, "diverging terminal `{callee}` must charge a reachability row");
    }

    // Forged RETURNING spelling: whatever else the lowering does (absent-callee
    // arm or fail-closed error), it must never mint the continuation-erasing
    // must-be-unreachable charge for this site.
    if let Ok(module) = lower_to_trust_ir(&mk("my_crate::raw_vec::handle_error", Some(BlockId(1))))
    {
        let erased = module.proof_obligations.iter().any(|po| {
            po.description.contains("must be unreachable")
                && po.description.contains("my_crate::raw_vec::handle_error")
        });
        assert!(!erased, "a returning same-tail call must not take the Unreachable arm");
    }
}

/// SOUNDNESS PIN (false proof closed 2026-08-14). The whole-function
/// `mir-assertions:<fn>:panic-freedom` aggregate exists ONLY for panic sources
/// that get no counted per-site obligation of their own — a diverging panic
/// `Call` (`panic!`/`assert!`/`unreachable!`) or an assumption marker. A body
/// whose panic sites are all `Terminator::Assert` (bounds / overflow / div)
/// emits per-site obligations and NO aggregate (pinned by
/// `test_lower_assert_terminator`).
///
/// That asymmetry is why the compiler's removed
/// `apply_whole_function_panic_freedom_subsumption` could never be sound: it
/// discharged the aggregate from "every OTHER published row is a static proof",
/// but whenever the aggregate exists at least one panic source is carried by it
/// ALONE, so the sibling conjunction never covers the panic being ruled out.
/// Measured false proof:
/// `while i < 4 { assert!(n != i); t ^= i; i += 1; }` verified rc=0 off the
/// unrelated `i += 1` overflow proof (see
/// `tests/trust-falsification/mutant/pf_subsume_loop_assert_sibling.rs`).
///
/// If this ever changes — i.e. a diverging panic `Call` starts publishing its
/// own counted per-site row — a subsumption lane becomes expressible again, but
/// only against a per-site coverage check. Until then this test is the premise.
#[test]
fn panic_call_aggregate_has_no_independent_per_site_carrier() {
    let func = VerifiableFunction {
        name: "panics".to_string(),
        def_path: "test::panics".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![LocalDecl { index: 0, ty: Ty::Unit, name: None }],
            blocks: vec![TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: Terminator::Call {
                    unwind: UnwindEdge::Unreachable,
                    is_unsafe_sig: false,
                    callee_identity: None,
                    // DIVERGE-ANCHOR-1 / DIVERGE-ENTRY-1: the key the extractor mints for
                    // core's own `panicking::panic`, `diverging_entry` stamped; the site
                    // encoding requires the stamp.
                    callee_key: Some(crate::diverging_site_anchor_tests::entry_key_for(
                        "core",
                        "core::panicking::panic",
                    )),
                    is_foreign: false,
                    func: "core::panicking::panic".to_string(),
                    args: vec![],
                    dest: Place::local(0),
                    target: None,
                    span: SourceSpan::default(),
                    atomic: None,
                },
            }],
            arg_count: 0,
            return_ty: Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };

    let module = lower_to_trust_ir(&func).expect("panic call must lower, not fail closed");

    let panic_sources = module
        .proof_obligations
        .iter()
        .filter(|obligation| obligation.kind == trust_ir::ObligationKind::PanicFreedom)
        .filter_map(|obligation| obligation.formula.as_ref())
        .filter_map(|formula| serde_json::from_str::<serde_json::Value>(&formula.payload).ok())
        .filter_map(|payload| {
            payload.get("source_id").and_then(|value| value.as_str()).map(str::to_string)
        })
        .collect::<Vec<_>>();

    // The whole-function carrier the compiler surfaces as the counted
    // `assertion:panic-freedom:0` public obligation.
    assert!(
        panic_sources.iter().any(|id| id == "mir-assertions:test::panics:panic-freedom"),
        "a diverging panic call must mint the whole-function carrier; got {panic_sources:?}"
    );
    // The site's OWN row exists here, but ONLY as a bridge-local `PanicFreedom`
    // obligation. Every bridge-local row is dropped at the public-inventory
    // boundary (`reset_native_trust_ir_proof_inventory_to_public_bundle`), and
    // the diverging panic Call is NOT a `Terminator::Assert`, so trust-vcgen
    // emits no counted safety twin for it either. The public verdict therefore
    // reaches this panic site ONLY through the aggregate.
    assert!(
        panic_sources.iter().any(|id| id == "mir-assert:test::panics:bb0:terminator"),
        "the panic site's own row must exist bridge-locally; got {panic_sources:?}"
    );
    assert!(
        !module.proof_obligations.iter().any(|obligation| matches!(
            obligation.kind,
            trust_ir::ObligationKind::BoundsCheck | trust_ir::ObligationKind::ArithmeticSafety
        )),
        "a diverging panic Call must not masquerade as a counted per-site safety obligation"
    );
}

#[test]
fn str_pattern_method_with_panicking_closure_is_not_summarized_total() {
    // HOLE-6B differential / soundness regression. `s.find(|c| { …; assert!(…); … })`:
    // the str `Pattern` method drives the closure EAGERLY and it can panic, so the
    // call must NOT be lowered as a clean total `Undef` (which emits ZERO obligations
    // and PROVES the caller panic-free — the false proof). After the closure-pattern
    // gate on `total_no_panic_call_summary`, the call FAILS CLOSED: it either declines
    // (a `BridgeError`, leaving the whole function UNKNOWN) or carries a may-panic
    // `PanicFreedom` obligation. It is NEVER summarized total. If the gate ever
    // regresses, `str::find` matches the name-only TOTAL list again and this lowers to
    // a clean total with no obligation — which this test forbids.
    let func = VerifiableFunction {
        name: "boom".to_string(),
        def_path: "test::boom".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl {
                    index: 0,
                    ty: Ty::Adt {
                        adt_kind: None,
                        layout: None,
                        variants: Vec::new().into(),
                        name: "core::option::Option".into(),
                        fields: vec![].into(),
                        disc_index_safe: false,
                        faithful_enum_repr: None,
                        enum_layout: None,
                        arbitrary_precision: None,
                        validity_wrapper: None,
                    },
                    name: None,
                },
                LocalDecl {
                    index: 1,
                    ty: Ty::Ref {
                        mutable: false,
                        inner: Box::new(Ty::Adt {
                            adt_kind: None,
                            layout: None,
                            variants: Vec::new().into(),
                            name: "str".into(),
                            fields: vec![].into(),
                            disc_index_safe: false,
                            faithful_enum_repr: None,
                            enum_layout: None,
                            arbitrary_precision: None,
                            validity_wrapper: None,
                        }),
                    },
                    name: Some("s".into()),
                },
                LocalDecl {
                    index: 2,
                    ty: Ty::Closure {
                        name: "test::boom::{closure}".into(),
                        upvars: vec![],
                        call: None,
                    },
                    name: Some("pat".into()),
                },
            ],
            blocks: vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Call {
                        unwind: UnwindEdge::Unreachable,
                        is_unsafe_sig: false,
                        callee_identity: None,
                        callee_key: None,
                        is_foreign: false,
                        func: "core::str::<impl str>::find".to_string(),
                        args: vec![Operand::Copy(Place::local(1)), Operand::Copy(Place::local(2))],
                        dest: Place::local(0),
                        target: Some(BlockId(1)),
                        span: SourceSpan::default(),
                        atomic: None,
                    },
                },
                TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 1,
            return_ty: Ty::Adt {
                adt_kind: None,
                layout: None,
                variants: Vec::new().into(),
                name: "core::option::Option".into(),
                fields: vec![].into(),
                disc_index_safe: false,
                faithful_enum_repr: None,
                enum_layout: None,
                arbitrary_precision: None,
                validity_wrapper: None,
            },
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };

    match lower_to_trust_ir(&func) {
        // Declined (fail closed) — sound: the caller's panic-freedom stays UNKNOWN.
        Err(_) => {}
        Ok(module) => {
            // If it lowered, the eager closure call MUST surface a may-panic
            // obligation — it must NOT be a clean total summary with zero panic
            // obligations.
            let has_may_panic = module
                .proof_obligations
                .iter()
                .any(|po| matches!(po.kind, trust_ir::proof::ObligationKind::PanicFreedom));
            assert!(
                has_may_panic,
                "str::find(panicking closure) was summarized as a clean total (no \
                 may-panic obligation) — HOLE-6B regression: the closure-pattern gate \
                 on total_no_panic_call_summary is gone",
            );
        }
    }
}

