// ---------------------------------------------------------------------------
// Trust (R3, generics): pre-monomorphization alias marker lowering
// ---------------------------------------------------------------------------

/// The identity-erased marker `trust-mir-extract` stamps on a param-bearing
/// projection alias (`<S as Serializer>::Ok`).
fn pre_mono_alias_marker_ty() -> Ty {
    Ty::Unsupported {
        kind: trust_types::PRE_MONO_ALIAS_KIND.to_string(),
        detail: trust_types::PRE_MONO_ALIAS_DETAIL.to_string(),
    }
}

#[test]
fn test_pre_mono_alias_marker_lowers_to_opaque_zero_field_struct() {
    // R3: a param-typed value slot lowers to a REGISTERED zero-field struct
    // (the Datatype/Coroutine precedent — an opaque per-binding symbol with no
    // interpreted equality and no arithmetic sort), NOT `Unit` (which trust-mc
    // concretizes to 0) and NOT a whole-function lowering error.
    let func = VerifiableFunction {
        name: "alias_param".to_string(),
        def_path: "test::alias_param".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: pre_mono_alias_marker_ty(), name: Some("opaque".into()) },
            ],
            blocks: vec![TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };

    let module = lower_to_trust_ir(&func).expect("pre-mono alias param must lower");
    let opaque = module
        .structs
        .iter()
        .find(|s| s.name == "opaque_alias::pre_monomorphization")
        .expect("marker must register the opaque struct");
    assert!(opaque.fields.is_empty(), "the opaque alias struct must have ZERO fields");
    assert_valid_module(&module);
}

#[test]
fn test_pre_mono_alias_marker_feeding_arith_fails_closed() {
    // SOUNDNESS (the no-arith invariant): a value of the marker type feeding a
    // primitive binary op must FAIL lowering/validation — never a silent 0
    // (the documented `Param -> Unit` fragility this arm deliberately avoids).
    let func = VerifiableFunction {
        name: "alias_arith".to_string(),
        def_path: "test::alias_arith".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::u32(), name: None },
                LocalDecl { index: 1, ty: pre_mono_alias_marker_ty(), name: Some("opaque".into()) },
            ],
            blocks: vec![TrustBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Add,
                        Operand::Copy(Place::local(1)),
                        Operand::Copy(Place::local(1)),
                    ),
                    span: SourceSpan::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: Ty::u32(),
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };

    match lower_to_trust_ir(&func) {
        Err(_) => {} // fail-closed at lowering — good
        Ok(module) => {
            let errors = validate_module(&module);
            assert!(
                !errors.is_empty(),
                "an Add over the opaque alias struct must fail lowering or validation; \
                 got a valid module: {module:?}"
            );
        }
    }
}

#[test]
fn test_monomorphic_alias_details_still_fail_type_mapping() {
    // SOUNDNESS (exact-scope regression): only the pre-monomorphization detail
    // gets the opaque-struct lowering; every other `TyKind::Alias` detail keeps
    // failing the whole-function lowering (fail-closed).
    let mut func = VerifiableFunction {
        name: "alias_mono".to_string(),
        def_path: "test::alias_mono".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl {
                    index: 1,
                    ty: Ty::Unsupported {
                        kind: trust_types::PRE_MONO_ALIAS_KIND.to_string(),
                        detail: "alias args nest ADTs too deep (9) to normalize safely".into(),
                    },
                    name: Some("opaque".into()),
                },
            ],
            blocks: vec![TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };
    lower_to_trust_ir(&func).expect_err("nest-too-deep alias must keep failing lowering");

    func.body.locals[1].ty = Ty::Unsupported {
        kind: trust_types::PRE_MONO_ALIAS_KIND.to_string(),
        detail: "opaque alias has no typing env to reveal against".into(),
    };
    lower_to_trust_ir(&func).expect_err("env-less opaque alias must keep failing lowering");
}

// ---------------------------------------------------------------------------
// Round-3 — keyed/Result collect dest gate, HashMap::insert key gate, bignum
// Shl, unsigned div_ceil, serde_json::Value indexing, Display local-impl
// resolution, and the first-party bundle context probe.
// ---------------------------------------------------------------------------

/// Round-3, engine level: the four new TYPE-/ARG-GATED absent-callee discharges
/// (bignum Shl, unsigned div_ceil, serde_json::Value index) DISCHARGE exactly
/// their gated shapes — havoc result,
/// NO `Assert(false)` marker, NO absent-callee obligation — while every
/// primitive/user/symbolic sibling KEEPS the full may-panic encoding. Collect and
/// map mutation always stay closed because producer/cleanup, hasher, and allocator
/// authority is erased.
#[test]
fn test_round3_absent_callee_gates_engine() {
    // A caller with an explicit local per argument. `arg_locals` are (ty, operand
    // constructor uses Copy); a `None` local slot means the argument is the given
    // constant operand instead.
    #[allow(clippy::type_complexity)]
    let mk = |func: &str, arg_tys: Vec<Ty>, const_args: Vec<Option<Operand>>, dest_ty: Ty| {
        let mut locals = vec![LocalDecl { index: 0, ty: dest_ty.clone(), name: None }];
        let mut args: Vec<Operand> = Vec::new();
        let mut next_local = 1usize;
        for (i, ty) in arg_tys.iter().enumerate() {
            match const_args.get(i).cloned().flatten() {
                Some(op) => args.push(op),
                None => {
                    locals.push(LocalDecl {
                        index: next_local,
                        ty: ty.clone(),
                        name: Some(format!("a{next_local}")),
                    });
                    args.push(Operand::Copy(Place::local(next_local)));
                    next_local += 1;
                }
            }
        }
        let arg_count = next_local - 1;
        VerifiableFunction {
            name: "caller".to_string(),
            def_path: "test::caller".to_string(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals,
                blocks: vec![
                    TrustBlock {
                        id: BlockId(0),
                        stmts: vec![],
                        terminator: Terminator::Call {
                            unwind: UnwindEdge::Unreachable,
                            is_unsafe_sig: false,
                            callee_identity: None,
                            callee_key: None,
                            is_foreign: false,
                            func: func.to_string(),
                            args,
                            dest: Place::local(0),
                            target: Some(BlockId(1)),
                            span: SourceSpan::default(),
                            atomic: None,
                        },
                    },
                    TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
                ],
                arg_count,
                return_ty: dest_ty,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    };
    let absent_callee_obligations = |module: &trust_ir::Module| -> usize {
        module
            .proof_obligations
            .iter()
            .filter(|o| {
                o.kind == trust_ir::ObligationKind::PanicFreedom
                    && o.description
                        .starts_with(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
            })
            .count()
    };
    let has_may_panic_marker = |module: &trust_ir::Module| -> bool {
        module.functions[0]
            .blocks
            .iter()
            .flat_map(|b| b.body.iter())
            .any(|n| matches!(n.inst, Inst::Assert { .. }))
    };

    let r = |inner: Ty| Ty::Ref { mutable: false, inner: Box::new(inner) };
    let rm = |inner: Ty| Ty::Ref { mutable: true, inner: Box::new(inner) };
    let ty_string = || Ty::adt("std::string::String", vec![]);
    let ty_user_key = || Ty::adt("my_crate::PanickyKey", vec![("x".into(), Ty::i64())]);
    let ty_hashmap = || Ty::adt("std::collections::HashMap", vec![]);
    let ty_btreemap = || Ty::adt("std::collections::BTreeMap", vec![("root".into(), Ty::u64())]);
    let ty_result = || {
        Ty::adt("std::result::Result", vec![("ok".into(), Ty::u64()), ("err".into(), Ty::u64())])
    };
    let ty_value = || Ty::adt("serde_json::Value", vec![]);
    let ty_map_iter = || Ty::adt("std::iter::Map", vec![]);
    let ty_str = || Ty::Slice { elem: Box::new(Ty::Int { width: 8, signed: false }) };
    let u128_uns = || Ty::Int { width: 128, signed: false };

    const KEYED_COLLECT: &str = "<std::iter::Map<std::collections::btree_map::Iter<'_, std::string::String, rational::Rat>, {closure@crates/ny-cert/src/selfcheck.rs:99:57: 99:65}> as std::iter::Iterator>::collect::<std::collections::BTreeMap<std::string::String, rational::Rat>>::<__trust_elem_bytes@72>";
    const KEYED_COLLECT_USER_KEY: &str = "<It as std::iter::Iterator>::collect::<std::collections::BTreeMap<my_crate::PanickyKey, u64>>::<__trust_elem_bytes@8>";
    const RESULT_VEC_COLLECT: &str = "<std::iter::Map<std::slice::Iter<'_, rational::Rat>, {closure@crates/ny-cert/src/schema.rs:200:14: 200:17}> as std::iter::Iterator>::collect::<std::result::Result<std::vec::Vec<std::string::String>, rational::RatError>>::<__trust_elem_bytes@16>";
    const RESULT_BTREE_COLLECT: &str = "<It as std::iter::Iterator>::collect::<std::result::Result<std::collections::BTreeMap<std::string::String, rational::Rat>, rational::RatError>>::<__trust_elem_bytes@72>";
    const RESULT_BTREE_COLLECT_USER_KEY: &str = "<It as std::iter::Iterator>::collect::<std::result::Result<std::collections::BTreeMap<my_crate::PanickyKey, rational::Rat>, rational::RatError>>::<__trust_elem_bytes@72>";

    // (callee, arg types, const-arg overrides, dest, expect_discharged, label)
    #[allow(clippy::type_complexity)]
    let cases: Vec<(&str, Vec<Ty>, Vec<Option<Operand>>, Ty, bool, &str)> = vec![
        // --- keyed/Result collect (dest place type + callee turbofish) ---
        (
            KEYED_COLLECT,
            vec![ty_map_iter()],
            vec![None],
            ty_btreemap(),
            false,
            "collect into BTreeMap<String, Rat>",
        ),
        (
            KEYED_COLLECT_USER_KEY,
            vec![ty_map_iter()],
            vec![None],
            ty_btreemap(),
            false,
            "collect into BTreeMap<UserKey, _>",
        ),
        (
            RESULT_VEC_COLLECT,
            vec![ty_map_iter()],
            vec![None],
            ty_result(),
            false,
            "collect into Result<Vec<String>, RatError>",
        ),
        (
            RESULT_BTREE_COLLECT,
            vec![ty_map_iter()],
            vec![None],
            ty_result(),
            false,
            "collect into Result<BTreeMap<String, Rat>, RatError>",
        ),
        (
            RESULT_BTREE_COLLECT_USER_KEY,
            vec![ty_map_iter()],
            vec![None],
            ty_result(),
            false,
            "collect into Result<BTreeMap<UserKey, _>, _>",
        ),
        // --- HashMap::insert key gate ---
        (
            "std::collections::HashMap::<K, V, S, A>::insert",
            vec![rm(ty_hashmap()), ty_string(), Ty::u64()],
            vec![None, None, None],
            Ty::u64(),
            false,
            "HashMap::insert String key",
        ),
        (
            "std::collections::HashMap::<K, V, S, A>::insert",
            vec![rm(ty_hashmap()), ty_ratio(ty_bigint()), Ty::u32()],
            vec![None, None, None],
            Ty::u64(),
            false,
            "HashMap::insert BigRational key",
        ),
        (
            "std::collections::HashMap::<K, V, S, A>::insert",
            vec![rm(ty_hashmap()), ty_user_key(), Ty::u64()],
            vec![None, None, None],
            Ty::u64(),
            false,
            "HashMap::insert user key",
        ),
        // --- bignum Shl ---
        (
            "std::ops::Shl::shl",
            vec![r(ty_bigint()), Ty::u32()],
            vec![None, None],
            ty_bigint(),
            false,
            "BigInt << u32",
        ),
        (
            "std::ops::Shl::shl",
            vec![r(ty_biguint()), Ty::usize()],
            vec![None, None],
            ty_biguint(),
            false,
            "BigUint << usize",
        ),
        (
            "std::ops::Shl::shl",
            vec![r(ty_bigint()), Ty::i64()],
            vec![None, None],
            ty_bigint(),
            false,
            "BigInt << i64 (signed rhs panics on negative)",
        ),
        (
            "std::ops::Shl::shl",
            vec![r(ty_bigint()), u128_uns()],
            vec![None, None],
            ty_bigint(),
            false,
            "BigInt << u128 (width > 64)",
        ),
        (
            "std::ops::Shl::shl",
            vec![Ty::u64(), Ty::u32()],
            vec![None, None],
            Ty::u64(),
            false,
            "u64 << u32 (primitive shift-overflow)",
        ),
        // --- unsigned div_ceil with literal nonzero divisor ---
        (
            "core::num::<impl u64>::div_ceil",
            vec![Ty::u64(), Ty::u64()],
            vec![None, Some(Operand::Constant(ConstValue::Uint(2, 64)))],
            Ty::u64(),
            true,
            "u64::div_ceil(2)",
        ),
        (
            "core::num::<impl u64>::div_ceil",
            vec![Ty::u64(), Ty::u64()],
            vec![None, None],
            Ty::u64(),
            false,
            "u64::div_ceil(symbolic)",
        ),
        (
            "core::num::<impl u64>::div_ceil",
            vec![Ty::u64(), Ty::u64()],
            vec![None, Some(Operand::Constant(ConstValue::Uint(0, 64)))],
            Ty::u64(),
            false,
            "u64::div_ceil(0) (division by zero)",
        ),
        (
            "core::num::<impl i64>::div_ceil",
            vec![Ty::i64(), Ty::i64()],
            vec![None, Some(Operand::Constant(ConstValue::Int(2)))],
            Ty::i64(),
            false,
            "i64::div_ceil (signed MIN/-1 overflow)",
        ),
        // --- serde_json::Value Index ---
        (
            "std::ops::Index::index",
            vec![r(ty_value()), r(ty_str())],
            vec![None, None],
            r(ty_value()),
            false,
            "serde_json::Value[..] read",
        ),
        (
            "std::ops::Index::index",
            vec![r(ty_hashmap()), r(ty_str())],
            vec![None, None],
            Ty::u64(),
            false,
            "HashMap[..] (missing-key panic)",
        ),
    ];

    for (callee, arg_tys, const_args, dest_ty, discharged, label) in cases {
        let module = lower_to_trust_ir(&mk(callee, arg_tys, const_args, dest_ty))
            .unwrap_or_else(|e| panic!("`{label}` (`{callee}`) must lower, not Err: {e:?}"));
        assert_valid_module(&module);
        if discharged {
            assert_eq!(
                absent_callee_obligations(&module),
                0,
                "{label}: a discharged callee must NOT raise the absent-callee obligation"
            );
            assert!(
                !has_may_panic_marker(&module),
                "{label}: a discharged callee must NOT emit the Assert(false) may-panic marker"
            );
        } else {
            assert!(
                has_may_panic_marker(&module),
                "{label}: a fail-closed callee must KEEP the Assert(false) may-panic marker"
            );
        }
    }
}

/// Round-3: `Display::fmt` on a LOCAL ADT receiver resolves to the ADT's bundled
/// in-module impl (the thiserror `#[error(transparent)]` shape —
/// `Display::fmt(&self.0, f)`) and is emitted as a REAL call into the impl body,
/// with NO absent-callee obligation; an UNBUNDLED receiver keeps the fail-closed
/// absent-callee encoding.
#[test]
fn test_round3_display_fmt_resolves_local_impl() {
    let ty_err = || Ty::adt("test::MyErr", vec![("code".into(), Ty::u64())]);
    let ty_fmt = || Ty::adt("std::fmt::Formatter", vec![]);
    let r = |inner: Ty| Ty::Ref { mutable: false, inner: Box::new(inner) };
    let rm = |inner: Ty| Ty::Ref { mutable: true, inner: Box::new(inner) };

    let mk_caller = |recv_ty: Ty| VerifiableFunction {
        name: "caller".to_string(),
        def_path: "test::caller".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::u64(), name: None },
                LocalDecl { index: 1, ty: recv_ty, name: Some("inner".into()) },
                LocalDecl { index: 2, ty: rm(ty_fmt()), name: Some("f".into()) },
            ],
            blocks: vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Call {
                        unwind: UnwindEdge::Unreachable,
                        is_unsafe_sig: false,
                        callee_identity: None,
                        callee_key: None,
                        is_foreign: false,
                        func: "std::fmt::Display::fmt".to_string(),
                        args: vec![Operand::Copy(Place::local(1)), Operand::Copy(Place::local(2))],
                        dest: Place::local(0),
                        target: Some(BlockId(1)),
                        span: SourceSpan::default(),
                        atomic: None,
                    },
                },
                TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 2,
            return_ty: Ty::u64(),
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };
    let impl_fn = VerifiableFunction {
        name: "<test::MyErr as std::fmt::Display>::fmt".to_string(),
        def_path: "<test::MyErr as std::fmt::Display>::fmt".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::u64(), name: None },
                LocalDecl { index: 1, ty: r(ty_err()), name: Some("self".into()) },
                LocalDecl { index: 2, ty: rm(ty_fmt()), name: Some("f".into()) },
            ],
            blocks: vec![TrustBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::Use(Operand::Constant(ConstValue::Uint(0, 64))),
                    span: SourceSpan::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 2,
            return_ty: Ty::u64(),
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };

    let absent_callee_obligations = |module: &trust_ir::Module| -> usize {
        module
            .proof_obligations
            .iter()
            .filter(|o| {
                o.kind == trust_ir::ObligationKind::PanicFreedom
                    && o.description
                        .starts_with(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
            })
            .count()
    };

    // BUNDLED impl: the call resolves to a REAL Inst::Call into functions[1].
    let module = lower_to_trust_ir_functions("display_resolve", &[mk_caller(r(ty_err())), impl_fn])
        .expect("Display::fmt with a bundled local impl must lower");
    assert_valid_module(&module);
    assert!(
        module.functions[0]
            .blocks
            .iter()
            .flat_map(|b| b.body.iter())
            .any(|n| matches!(&n.inst, Inst::Call { callee, .. } if callee.index() == 1)),
        "Display::fmt on a bundled local ADT must emit a real call into the impl body"
    );
    assert_eq!(
        absent_callee_obligations(&module),
        0,
        "a locally-resolved Display::fmt must not raise the absent-callee obligation"
    );

    // UNBUNDLED receiver: stays on the fail-closed absent-callee arm.
    let module = lower_to_trust_ir(&mk_caller(r(Ty::adt("test::OtherErr", vec![]))))
        .expect("unbundled Display::fmt receiver must still lower fail-soft");
    assert_valid_module(&module);
    assert_eq!(
        absent_callee_obligations(&module),
        1,
        "an unbundled Display::fmt receiver must KEEP the absent-callee obligation"
    );
}

/// Round-3 (first-party bundling gap): the CONTEXT-AWARE survivor probe. A
/// function whose body invokes a closure through the `FnOnce::call_once` shim
/// hard-fails ALONE (the closure body is not in the module), but the probe —
/// which registers every candidate's name/signature — correctly reports it
/// lowers IN CONTEXT; with the closure missing from the candidate set the probe
/// stays fail-closed.
#[test]
fn test_round3_bundle_context_probe() {
    let closure_name = "test::probe::{closure#0}".to_string();
    let closure_ty =
        Ty::Closure { name: closure_name.clone(), upvars: vec![Ty::u32()], call: None };

    let caller = VerifiableFunction {
        name: "probe_caller".to_string(),
        def_path: "test::probe_caller".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::u32(), name: None },
                LocalDecl { index: 1, ty: Ty::u32(), name: Some("captured".into()) },
                LocalDecl { index: 2, ty: closure_ty.clone(), name: Some("closure".into()) },
                LocalDecl { index: 3, ty: Ty::Tuple(vec![Ty::u32()]), name: Some("args".into()) },
                LocalDecl { index: 4, ty: Ty::u32(), name: Some("result".into()) },
            ],
            blocks: vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![
                        Statement::Assign {
                            place: Place::local(2),
                            rvalue: Rvalue::Aggregate(
                                AggregateKind::Closure {
                                    name: closure_name.clone(),
                                    captures: vec![],
                                    call_kind: ClosureCallKind::FnOnce,
                                },
                                vec![Operand::Copy(Place::local(1))],
                            ),
                            span: SourceSpan::default(),
                        },
                        Statement::Assign {
                            place: Place::local(3),
                            rvalue: Rvalue::Aggregate(
                                AggregateKind::Tuple,
                                vec![Operand::Constant(ConstValue::Uint(7, 32))],
                            ),
                            span: SourceSpan::default(),
                        },
                    ],
                    terminator: Terminator::Call {
                        unwind: UnwindEdge::Unreachable,
                        is_unsafe_sig: false,
                        callee_identity: None,
                        callee_key: None,
                        is_foreign: false,
                        func: "core::ops::function::FnOnce::call_once".to_string(),
                        args: vec![Operand::Move(Place::local(2)), Operand::Move(Place::local(3))],
                        dest: Place::local(4),
                        target: Some(BlockId(1)),
                        span: SourceSpan::default(),
                        atomic: None,
                    },
                },
                TrustBlock {
                    id: BlockId(1),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Copy(Place::local(4))),
                        span: SourceSpan::default(),
                    }],
                    terminator: Terminator::Return,
                },
            ],
            arg_count: 1,
            return_ty: Ty::u32(),
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };
    let closure_body = VerifiableFunction {
        name: closure_name.clone(),
        def_path: closure_name.clone(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::u32(), name: None },
                LocalDecl { index: 1, ty: closure_ty, name: Some("self".into()) },
                LocalDecl { index: 2, ty: Ty::u32(), name: Some("arg".into()) },
            ],
            blocks: vec![TrustBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::Use(Operand::Copy(Place::local(2))),
                    span: SourceSpan::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 2,
            return_ty: Ty::u32(),
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };

    let empty: std::collections::HashSet<String> = std::collections::HashSet::new();
    // ALONE the caller's shim has no closure body. It used to hard-fail (the
    // alone-probe misverdict the context probe fixes); since fix6
    // CLOSURE-ABSENT-CALLEE it lowers, but only as the fail-closed absent callee:
    // a may-panic row and no call.
    let alone = lower_to_trust_ir(&caller).expect("caller lowers alone as an absent call");
    assert!(
        alone.proof_obligations.iter().any(|o| o
            .description
            .starts_with(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)),
        "ALONE, the shim must be the fail-closed absent callee"
    );
    assert!(
        !alone.functions[0]
            .blocks
            .iter()
            .flat_map(|b| b.body.iter())
            .any(|n| matches!(n.inst, Inst::Call { .. })),
        "ALONE, there is no body to call"
    );
    // IN CONTEXT (closure body registered) it lowers.
    assert!(
        verifiable_function_lowers_in_module_context(
            &[caller.clone(), closure_body.clone()],
            0,
            &empty,
            &empty
        ),
        "caller must lower in the candidate set's context"
    );
    // And the closure body itself probes fine at its own index.
    assert!(
        verifiable_function_lowers_in_module_context(
            &[caller.clone(), closure_body],
            1,
            &empty,
            &empty
        ),
        "closure body must lower in context"
    );
    // With the closure missing from the candidate set the caller is KEPT: its
    // shim is the fail-closed absent callee shown above, which is what keeps a
    // dropped closure from costing its caller (fix6 CLOSURE-ABSENT-CALLEE).
    assert!(
        verifiable_function_lowers_in_module_context(&[caller], 0, &empty, &empty),
        "a caller whose shim's closure body is not a candidate lowers as an absent call"
    );
    // Out-of-range index fails closed.
    assert!(!verifiable_function_lowers_in_module_context(&[], 0, &empty, &empty));
}

/// Round-3: `Rev<Range<usize>>` / bare `Range<int>` receivers are recognized
/// TOTAL for `Iterator::next` (the batch-44 `exact::solve_system` reversed
/// elimination loop), while `Range<UserStep>` stays fail-closed.
///
/// Round-5: `RangeInclusive<int>` (extracted shape: `start`/`end` ints + the
/// `exhausted` Bool) joins the total bases — batch-49's residual
/// `exact::solve_system` `for c in col..=n` loops — while
/// `RangeInclusive<UserStep>` (ADT bounds driving a user `Step`) stays
/// fail-closed.
#[test]
fn test_round3_range_iterator_next_discharges() {
    let ty_range = || {
        Ty::adt("std::ops::Range", vec![("start".into(), Ty::usize()), ("end".into(), Ty::usize())])
    };
    let ty_rev_range = || Ty::adt("std::iter::Rev", vec![("iter".into(), ty_range())]);
    let ty_user_range = || {
        Ty::adt(
            "std::ops::Range",
            vec![
                ("start".into(), Ty::adt("my_crate::Step", vec![])),
                ("end".into(), Ty::adt("my_crate::Step", vec![])),
            ],
        )
    };
    let rm = |inner: Ty| Ty::Ref { mutable: true, inner: Box::new(inner) };

    let mk = |recv_ty: Ty| VerifiableFunction {
        name: "caller".to_string(),
        def_path: "test::caller".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::u64(), name: None },
                LocalDecl { index: 1, ty: recv_ty, name: Some("it".into()) },
            ],
            blocks: vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Call {
                        unwind: UnwindEdge::Unreachable,
                        is_unsafe_sig: false,
                        callee_identity: None,
                        callee_key: None,
                        is_foreign: false,
                        func: "std::iter::Iterator::next".to_string(),
                        args: vec![Operand::Copy(Place::local(1))],
                        dest: Place::local(0),
                        target: Some(BlockId(1)),
                        span: SourceSpan::default(),
                        atomic: None,
                    },
                },
                TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 1,
            return_ty: Ty::u64(),
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };
    let absent_callee_obligations = |module: &trust_ir::Module| -> usize {
        module
            .proof_obligations
            .iter()
            .filter(|o| {
                o.kind == trust_ir::ObligationKind::PanicFreedom
                    && o.description
                        .starts_with(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
            })
            .count()
    };

    for (recv, discharged, label) in [
        (rm(ty_range()), true, "Range<usize>::next"),
        (rm(ty_rev_range()), true, "Rev<Range<usize>>::next"),
        (rm(ty_user_range()), false, "Range<UserStep>::next"),
        // Round-5 — the REAL extracted `RangeInclusive<usize>` shape (`start`/`end`
        // ints + the `exhausted` Bool the exclusive-Range all-Int gate could not
        // cover) now DISCHARGES.
        (
            rm(Ty::adt(
                "std::ops::RangeInclusive",
                vec![
                    ("start".into(), Ty::usize()),
                    ("end".into(), Ty::usize()),
                    ("exhausted".into(), Ty::Bool),
                ],
            )),
            true,
            "RangeInclusive<usize>::next (Round-5)",
        ),
        // Round-5 fail-closed control — ADT bounds drive a user `Step` whose
        // `forward`/`backward` may panic; and a Bool-only lookalike carries no
        // integer cursor at all. Both must KEEP the obligation.
        (
            rm(Ty::adt(
                "std::ops::RangeInclusive",
                vec![
                    ("start".into(), Ty::adt("my_crate::Step", vec![])),
                    ("end".into(), Ty::adt("my_crate::Step", vec![])),
                    ("exhausted".into(), Ty::Bool),
                ],
            )),
            false,
            "RangeInclusive<UserStep>::next",
        ),
        (
            rm(Ty::adt("std::ops::RangeInclusive", vec![("exhausted".into(), Ty::Bool)])),
            false,
            "RangeInclusive with no integer cursor",
        ),
    ] {
        let module = lower_to_trust_ir(&mk(recv))
            .unwrap_or_else(|e| panic!("{label} must lower, not Err: {e:?}"));
        assert_valid_module(&module);
        assert_eq!(
            absent_callee_obligations(&module) == 0,
            discharged,
            "{label}: discharge expectation mismatch"
        );
    }
}

#[test]
fn recognized_total_no_panic_gate_reuses_audited_surfaces_only() {
    use crate::lower::callee_is_recognized_total_no_panic as total;

    // MUST MATCH — the exact real-crate spellings the interprocedural pf call
    // gate observes (ny-cert gateLCG PF_CALLGATE ground truth), each covered by
    // an EXISTING audited surface:
    // extractor-stamped total `?`-desugar `Try::branch` (canonical trait path).
    assert!(total(
        "<core::result::Result<(), ny_cert::sbar::SbarError> as core::ops::try_trait::Try>::branch::<__trust_args@b772cf92808c9f6911e33dddbc40bc11>::<__trust_try_total>"
    ));
    // core primitive wrapping arithmetic (modular-BinOp family).
    assert!(total("core::num::<impl u128>::wrapping_sub"));
    assert!(total("core::num::<impl i128>::wrapping_neg")); // EXACT_TOTAL
    // Hardened orphan-safe String::from(&str) arm.
    assert!(total(
        "<alloc::string::String as core::convert::From<&str>>::from::<__trust_args@d440356f4eda3cbfcbc3129892185705>"
    ));

    // MUST NOT MATCH — fail-closed surfaces:
    // genuinely may-panic std callees.
    assert!(!total("core::option::Option::unwrap"));
    assert!(!total("core::option::Option::expect"));
    // panic entrypoints themselves.
    assert!(!total("core::panicking::panic"));
    assert!(!total("core::panicking::panic_fmt"));
    // user-crate shadow of a recognized std name (path anchor rejects).
    assert!(!total("mycrate::wrapping_sub"));
    assert!(!total("mycrate::num::wrapping_sub"));
    // a user `Try` trait spoof and a bare marker with no trait identity.
    assert!(!total("<mycrate::T as mycrate::Try>::branch::<__trust_try_total>"));
    assert!(!total("foo::<__trust_try_total>"));
    // `HashMap::new` — RETIRED from EXACT_TOTAL 2026-08-21. This exact spelling was
    // asserted as MUST-MATCH above until then, on the claim that it "does NO hashing/
    // user code/allocation until a first insert". It reaches a PANIC:
    //   map.rs:270 new() -> Default::default() -> random.rs:149 RandomState::new()
    //   -> random.rs:67 thread_local!(static KEYS = { .. })   <- LAZY, not `const {`
    //   -> random.rs:71 KEYS.with(..) -> local.rs:427 LocalKey::with
    //   -> Err(err) => panic_access_error(err)
    // i.e. constructing a HashMap during or after TLS teardown panics. `LocalKey::with`
    // is trusted nowhere else in this crate — false proof #13 was this same lazy-TLS
    // mechanism one call shallower.
    assert!(!total(
        "std::collections::hash::map::HashMap::<alloc::string::String, alloc::string::String>::new::<__trust_args@12f642111528f722217177b73963a87d>"
    ));
    assert!(!total("std::collections::hash::map::HashMap::new"));
    // The keyless READS stay total — they are plain field reads, no RandomState.
    assert!(total("std::collections::HashMap::len"));
    assert!(total("std::collections::HashMap::is_empty"));

    // Orphan-safe primitive arms — REMOVED 2026-08-22 (R41), NOW MUST **NOT** MATCH.
    // These three arms anchored `Self` (and the `From`/`TryFrom` SOURCE) on a BARE
    // `u64`/`usize`/… spelling, justified by "no user type can be named a bare
    // `u128`/`usize`/…". THAT IS FALSE — they are legal generic-parameter names and a
    // `ty::Param` renders BARE — so the HONEST and the FORGED spellings are the same
    // bytes and no string predicate can separate them. Every assertion below is
    // therefore a pair: the "honest" spelling and its forgery are indistinguishable
    // here, and both must be refused. See `primitive_self_bare_spellings_are_forgeable`.
    assert!(!total("<u128 as core::convert::From<u64>>::from"));
    assert!(!total(
        "<usize as core::cmp::Ord>::max::<__trust_args@c8da168efb3f7e435104899fbc5ff592>"
    ));
    assert!(!total("<i64 as core::cmp::Ord>::min"));
    assert!(!total("<usize as core::convert::TryFrom<i128>>::try_from"));
    // The spoof/boundary rejections that were already correct stay correct.
    assert!(!total("<mycrate::MyInt as core::convert::From<u64>>::from"));
    assert!(!total("<mycrate::T as core::cmp::Ord>::max"));
    assert!(!total("<u128 as core::convert::From<mycrate::T>>::from"));
    assert!(!total("<usize as mycrate::cmp::Ord>::max"));
    assert!(!total("<u128 as mycrate::convert::From<u64>>::from"));
    // `Ord::clamp` panics when `min > max` — excluded then, excluded now.
    assert!(!total("<usize as core::cmp::Ord>::clamp"));
    assert!(!total("<mycrate::MyInt as core::convert::TryFrom<u32>>::try_from"));
    assert!(!total("<u32 as core::convert::TryFrom<mycrate::T>>::try_from"));
    assert!(!total("<u32 as mycrate::convert::TryFrom<usize>>::try_from"));

    // Orphan-safe container arms (Vec deref / ops::Range into_iter) — MUST
    // MATCH the exact PF_CALLGATE census spellings (gateLCG ground truth):
    assert!(total(
        "<alloc::vec::Vec<ny_cert::rational::Rat> as core::ops::deref::Deref>::deref::<__trust_args@416b1025be389d71de3b5262e4ff128f>"
    ));
    // …the DerefMut twin (same alloc impl family, same (ptr,len) body) and the
    // plain re-export renderings.
    assert!(total("<alloc::vec::Vec<u8> as core::ops::deref::DerefMut>::deref_mut"));
    assert!(total("<std::vec::Vec<alloc::string::String> as std::ops::Deref>::deref"));
    assert!(total(
        "<core::ops::range::Range<usize> as core::iter::traits::collect::IntoIterator>::into_iter::<__trust_args@facf37d263000c8041ccc50ccaef0cdc>"
    ));
    assert!(total("<std::ops::Range<usize> as std::iter::IntoIterator>::into_iter"));
    // into_iter is the blanket IDENTITY for ANY payload (the payload's Step
    // runs only in `next`, which the gate does not match) — a user payload is
    // admitted here and its `next` keeps its own obligation.
    assert!(total(
        "<core::ops::range::Range<mycrate::Step> as core::iter::traits::collect::IntoIterator>::into_iter"
    ));

    // …and their spoof/boundary rejections:
    // a user type named Vec / Range (its Deref/IntoIterator impl is
    // orphan-LEGAL and can run arbitrary user code).
    assert!(!total("<mycrate::Vec as core::ops::deref::Deref>::deref"));
    assert!(!total("<mycrate::vec::Vec<u8> as core::ops::deref::Deref>::deref"));
    assert!(!total("<mycrate::Range as core::iter::traits::collect::IntoIterator>::into_iter"));
    assert!(!total("<mycrate::MyRange as std::iter::IntoIterator>::into_iter"));
    // a user trait namespace spoof on the genuine std Self.
    assert!(!total("<alloc::vec::Vec<u8> as mycrate::Deref>::deref"));
    assert!(!total("<alloc::vec::Vec<u8> as mycrate::ops::Deref>::deref"));
    assert!(!total("<core::ops::range::Range<usize> as mycrate::IntoIterator>::into_iter"));
    assert!(!total(
        "<core::ops::range::Range<usize> as mycrate::iter::collect::IntoIterator>::into_iter"
    ));
    // slice indexing PANICS out of bounds — no deref confusion may admit it.
    assert!(!total("<alloc::vec::Vec<u8> as core::ops::index::Index<usize>>::index"));
    assert!(!total("<alloc::vec::Vec<u8> as core::ops::index::IndexMut<usize>>::index_mut"));
    // trait/method cross-pair confusion fails both identity conjuncts.
    assert!(!total("<alloc::vec::Vec<u8> as core::ops::deref::Deref>::deref_mut"));
    // panicking inherent Vec methods stay unrecognized (no arm covers them;
    // `Vec::pop` alone is a separately-committed EXACT_TOTAL entry, A6 family).
    assert!(!total("alloc::vec::Vec::remove"));
    assert!(!total("alloc::vec::Vec::swap_remove"));
    assert!(!total("alloc::vec::Vec::insert"));
    // the NEW range API's `core::range::Range` is a DIFFERENT type with a
    // NON-identity IntoIterator body — deliberately excluded, must reject.
    assert!(!total(
        "<core::range::Range<usize> as core::iter::traits::collect::IntoIterator>::into_iter"
    ));
    // RangeInclusive (any spelling) is not census-present and not verified —
    // must reject in both the legacy and new-API paths.
    assert!(!total(
        "<core::ops::range::RangeInclusive<usize> as core::iter::traits::collect::IntoIterator>::into_iter"
    ));
    assert!(!total("<std::ops::RangeInclusive<usize> as std::iter::IntoIterator>::into_iter"));

    // Round-3: unsigned-payload `Range<uN>::next`. RETIRED 2026-08-22 (R42) — these two
    // lines USED TO BE `assert!(total(..))`, MUST-MATCH pins on the PF_CALLGATE census
    // spelling (random_problem / random_simplex_lp blocker). They are now NEGATIVE, and
    // the flip is the fix, not a regression to repair.
    //
    // The arm's payload conjunct was `PRIMITIVE_UINT_SPELLINGS.contains(payload.trim())`
    // — a rendered substring against six words. `usize` is a legal generic-parameter
    // name and a `ty::Param` renders BARE, so the census spelling below is BYTE-IDENTICAL
    // to what a hostile crate renders, and the deployed driver was measured accepting it:
    //     [PF_ZEROGATE] fn=S::attack_range_nostep arm=bridge-total \
    //       callee=<core::ops::range::Range<usize> as core::…::Iterator>::next
    // (fixture: `pub fn attack_range_nostep<usize>(r: &mut Range<usize>) -> … where
    // Range<usize>: Iterator` — note it never names `Step` and needs NO feature gate,
    // refuting the "held closed because `Step` is unstable" rationale this arm shipped
    // with). At a payload whose `Step::forward_checked` returns `None`, core's default
    // `spec_next` hits `.expect("`Step` invariants not upheld")` on every call.
    //
    // THE HONEST CENSUS TRAFFIC DOES NOT NEED THIS ARM. `all_callee_keys_registry_or_
    // bridge_total` tries the TyCtxt-anchored registry FIRST (trust_verify.rs:18569)
    // and only then this string lane (:18575), and the registry decides `Range` by a
    // real `TyKind` test (trust_verify.rs:27410-27412). Measured on the deployed driver:
    // honest `Range<u64>::next`, honest `Range<usize>::next`, and a `for i in 0..n`
    // desugar (both the `into_iter` hop and the `next`) ALL printed `arm=registry`;
    // none printed `arm=bridge-total`. Anything the registry declines is declined
    // because the payload is NOT TyCtxt-confirmably an integer — precisely the case
    // that must fail closed. If a census function regresses to unknown here, that is the
    // correct direction: it means its range payload was never type-confirmed.
    assert!(!total(
        "<core::ops::range::Range<usize> as core::iter::traits::iterator::Iterator>::next::<__trust_args@facf37d263000c8041ccc50ccaef0cdc>"
    ));
    assert!(!total("<std::ops::Range<u64> as std::iter::Iterator>::next"));
    // …the spoof/boundary rejections that were already here and still hold (they were
    // never the load-bearing part — the arm's failure mode was accepting a `ty::Param`
    // SPELLED like a primitive, not accepting an honestly-spelled user type):
    // a USER Step payload — the default spec_next body runs user
    // `forward_checked` and then `.expect(..)`: a REAL panic path.
    assert!(!total(
        "<core::ops::range::Range<mycrate::Step> as core::iter::traits::iterator::Iterator>::next"
    ));
    // signed / non-bare payloads decline (census is unsigned-only).
    assert!(!total(
        "<core::ops::range::Range<i64> as core::iter::traits::iterator::Iterator>::next"
    ));
    // a user type named Range / user trait namespace.
    assert!(!total("<mycrate::Range<usize> as core::iter::traits::iterator::Iterator>::next"));
    assert!(!total("<core::ops::range::Range<usize> as mycrate::Iterator>::next"));
    assert!(!total("<core::ops::range::Range<usize> as mycrate::iter::iterator::Iterator>::next"));
    // RangeInclusive::next is a DIFFERENT stateful impl — reject in every spelling.
    assert!(!total(
        "<core::ops::range::RangeInclusive<usize> as core::iter::traits::iterator::Iterator>::next"
    ));
    assert!(!total("<std::ops::RangeInclusive<usize> as std::iter::Iterator>::next"));
    // next_back is NOT admitted (not census-present, separate verification).
    assert!(!total(
        "<core::ops::range::Range<usize> as core::iter::traits::double_ended::DoubleEndedIterator>::next_back"
    ));
    assert!(!total(
        "<core::ops::range::Range<usize> as core::iter::traits::iterator::Iterator>::next_back"
    ));
    // other Iterator surfaces (count carries a real `.expect`) reject on method.
    assert!(!total(
        "<core::ops::range::Range<usize> as core::iter::traits::iterator::Iterator>::count"
    ));
    // the new-API `core::range::Range` stays excluded here too.
    assert!(!total("<core::range::Range<usize> as core::iter::traits::iterator::Iterator>::next"));

    // ny_cert `Rat` comparison family — RETIRED 2026-08-21. These two spellings were
    // asserted as MUST-MATCH until then ("the audited ny_cert Rat comparison family",
    // pinned to the exact certify_upper_inner blocker). The grant was MANIFEST — 4 fns
    // were registered panic-free on it — and false: `Rat::cmp` reaches a LAZY
    // `ARENA.try_with`, and the very run that used the grant ALSO reported
    //   error: Trust strict verification failed for `<Rat as core::cmp::Ord>::cmp`
    // 32 lines before discharging that same callee as `arm=bridge-total`.
    // Re-admission must be CONDITIONAL on the leaf being proved (registry-side, in
    // `discharge_call_arm_admits`), not a name match here.
    assert!(!total(
        "<ny_cert::rational::Rat as core::cmp::PartialOrd>::gt::<__trust_args@48d4cf92f99a4804b5093714385ba91d>"
    ));
    assert!(!total("<ny_cert::rational::Rat as core::cmp::Ord>::cmp"));
    assert!(!total("<ny_cert::rational::Rat as core::cmp::Ord>::min"));
    assert!(!total("<ny_cert::rational::Rat as core::cmp::PartialOrd>::partial_cmp"));
    // `clamp` was ALREADY excluded (its default body asserts `min <= max`) and stays so.
    assert!(!total("<ny_cert::rational::Rat as core::cmp::Ord>::clamp"));
    assert!(!total("<mycrate::Foo as core::cmp::PartialOrd>::gt::<__trust_args@x>"));
    assert!(!total("<ny_cert::rational::Rat as mycrate::PartialOrd>::le"));
    assert!(!total("ny_cert::rational::Rat::le"));

    // CANARY safety (sqrt_upper): its in-crate genuine-boundary callee and its
    // bignum arithmetic must stay unrecognized (F5 carries only the audited
    // to_biguint/bits ACCESSORS, never arithmetic or local fns) — and no
    // bignum spelling may ride the new container arms.
    assert!(!total("ny_cert::rational::isqrt_floor"));
    assert!(!total("num_bigint::biguint::BigUint::sub"));
    assert!(!total("num_bigint::bigint::BigInt::to_biguint"));
    assert!(!total("<num_bigint::bigint::BigInt as core::ops::deref::Deref>::deref"));
    assert!(!total("<num_bigint::bigint::BigInt as core::cmp::Ord>::cmp"));
}

/// Trust (L2a): the zero-obligation / call-discharge gates must agree with the
/// bridge arm on the E6 checked-primitive stamp, exactly as LEVER 1 makes them
/// agree on the wrapping stamp. Measured on stage 1 before this arm: a body whose
/// only call was a stamped `i64::checked_add` published `unknown`
/// (`native-verification-gap`), while `u32::wrapping_add` published `proved`
/// (`no_obligations`).
#[test]
fn extractor_stamped_checked_family_is_lane_consistent_and_fail_closed() {
    use crate::lower::callee_is_recognized_total_no_panic as total;

    for stamped in [
        "@trust-rustc-checked-primitive-method::core::num::<impl i8>::checked_add",
        "@trust-rustc-checked-primitive-method::core::num::<impl i64>::checked_add",
        "@trust-rustc-checked-primitive-method::core::num::<impl i64>::checked_sub",
        "@trust-rustc-checked-primitive-method::core::num::<impl i128>::checked_mul",
    ] {
        assert!(total(stamped), "extractor-stamped checked primitive method: {stamped}");
    }
    for bad in [
        "@trust-rustc-checked-primitive-method::core::num::<impl u64>::checked_add",
        "@trust-rustc-checked-primitive-method::core::num::<impl isize>::checked_add",
        "@trust-rustc-checked-primitive-method::core::num::<impl i64>::checked_div",
        "@trust-rustc-checked-primitive-method::core::num::<impl i64>::checked_neg",
        "@trust-rustc-checked-primitive-method::evil::num::<impl i64>::checked_add",
        "@trust-rustc-checked-primitive-method::std::num::<impl i64>::checked_add",
        "@trust-rustc-checked-primitive-method::core::num::<impl i64>::checked_add::sfx",
        "@trust-rustc-checked-primitive-method::",
        "mycrate::checked_add",
        "mycrate::@trust-rustc-checked-primitive-method::core::num::<impl i64>::checked_add",
    ] {
        assert!(!total(bad), "must not be recognized total: {bad}");
    }
}

/// LEVER 1 — the EXTRACTOR-STAMPED wrapping family is a LANE-CONSISTENCY gap, not
/// a new grant: the BARE spelling `core::num::<impl u64>::wrapping_add` was already
/// admitted by the gate's tail (pinned in the test above), while the same call
/// carrying the compiler's `@trust-rustc-total-primitive-method::` authentication
/// stamp was REFUSED — the stamp defeats both `has_trusted_std_root` and
/// `is_exact_primitive_num_method`, neither of which expects a `@`-prefixed root.
///
/// MEASURED TARGETS (ny .gatelogs/R40.log, `TRUST_PF_MATCH_TRACE=1`) — all three
/// `arm=NONE (blocks registration)` lines of this family, verbatim:
///   ny_cert::crown_deep::f64_next_up_compat  …<impl u64>::wrapping_add
///   ny_cert::generate::Lcg::new              …<impl u64>::wrapping_mul
///   ny_cert::json::hex_value                 …<impl u8>::wrapping_sub
///
/// The gate delegates to the ONE shared `trust_types::RustcTotalPrimitiveMethod`
/// grammar (whose own anti-forgery suite lives beside it), so this test pins the
/// WIRING — that the gate consults the classifier at all — plus the boundary cases
/// that would matter if someone re-implemented the prefix match by hand here.
#[test]
fn extractor_stamped_wrapping_family_is_lane_consistent_and_fail_closed() {
    use crate::lower::callee_is_recognized_total_no_panic as total;

    // MUST MATCH — the three exact R40 blocker spellings, plus the remaining
    // admitted widths, in BOTH the stamped and bare renderings (lane consistency
    // is the whole point: the two must agree).
    for stamped in [
        "@trust-rustc-total-primitive-method::core::num::<impl u64>::wrapping_add",
        "@trust-rustc-total-primitive-method::core::num::<impl u64>::wrapping_mul",
        "@trust-rustc-total-primitive-method::core::num::<impl u8>::wrapping_sub",
        "@trust-rustc-total-primitive-method::core::num::<impl u16>::wrapping_add",
        "@trust-rustc-total-primitive-method::core::num::<impl u32>::wrapping_mul",
    ] {
        assert!(total(stamped), "extractor-stamped total primitive method: {stamped}");
    }
    assert!(total("core::num::<impl u64>::wrapping_add"), "the bare twin already matched");

    // MUST NOT MATCH — the classifier's grammar boundaries, re-pinned AT THE GATE
    // so a hand-rolled `starts_with(PREFIX)` replacement fails here rather than in
    // a gate log. Each is a real spelling the stamp must never license.
    for bad in [
        // Foreign / shadowed roots under the stamp.
        "@trust-rustc-total-primitive-method::evil::num::<impl u64>::wrapping_add",
        "@trust-rustc-total-primitive-method::std::num::<impl u64>::wrapping_add",
        "@trust-rustc-total-primitive-method::core::evil::<impl u64>::wrapping_add",
        // Carriers OUTSIDE the E6 machine-domain boundary (signed, u128, usize).
        "@trust-rustc-total-primitive-method::core::num::<impl i64>::wrapping_add",
        "@trust-rustc-total-primitive-method::core::num::<impl u128>::wrapping_add",
        "@trust-rustc-total-primitive-method::core::num::<impl usize>::wrapping_add",
        // Same-prefix METHOD lookalikes, including the panicking division family.
        "@trust-rustc-total-primitive-method::core::num::<impl u64>::wrapping_add_signed",
        "@trust-rustc-total-primitive-method::core::num::<impl u64>::wrapping_div",
        "@trust-rustc-total-primitive-method::core::num::<impl u64>::wrapping_rem",
        "@trust-rustc-total-primitive-method::core::num::<impl u64>::unchecked_add",
        // Malformed / truncated / over-long stamped paths.
        "@trust-rustc-total-primitive-method::core::num::<impl u64>::wrapping_add::suffix",
        "@trust-rustc-total-primitive-method::core::num::wrapping_add",
        "@trust-rustc-total-primitive-method::core::num::<impl u64>",
        "@trust-rustc-total-primitive-method::",
        // A DIFFERENT stamp namespace must not be honoured by this arm: the
        // refutation-only marker admits signed/128/pointer-sized carriers that the
        // E6 totality lane deliberately excludes.
        "@trust-rustc-wrapping-refutation-method::core::num::<impl i64>::wrapping_add",
        // A user function that merely spells the marker inside its own path.
        "mycrate::@trust-rustc-total-primitive-method::core::num::<impl u64>::wrapping_add",
    ] {
        assert!(!total(bad), "stamped-marker boundary must fail closed: {bad}");
    }
}

/// LEVER 2 — `<str as alloc::string::ToString>::to_string`, the single largest
/// zero-obligation registration blocker in ny .gatelogs/R40.log (18 `arm=NONE`
/// lines, more than any other callee).
///
/// THE FALSE PROOF THIS TEST EXISTS TO PREVENT. There is no `impl ToString for str`.
/// The call resolves to the BLANKET `impl<T: fmt::Display + ?Sized> ToString for T`
/// (library/alloc/src/string.rs:2918), whose `SpecToString` DEFAULT body
/// (string.rs:2931-2947) ends in
/// `fmt::Display::fmt(self, &mut formatter).expect("a Display implementation
/// returned an error unexpectedly")` — a LIVE panic reachable for every `Self`
/// whose `Display` impl can return `Err`, i.e. every caller-written one.
/// Panic-freedom holds ONLY for the `Self`s that `to_string_str!`
/// (string.rs:3065-3099) specializes; `str` is one of them. So a recognizer keyed on
/// the TRAIT, or on the `::to_string` method tail, would grant panic-freedom to
/// arbitrary user `Display` code. Both conjuncts are load-bearing and this test
/// kills each one independently.
#[test]
fn str_to_string_bare_spelling_is_forgeable_and_must_stay_rejected() {
    use crate::lower::callee_is_recognized_total_no_panic as total;

    // REGRESSION PIN for a false proof caught in adversarial review before it
    // shipped. An `is_str_to_string_callee` arm accepted this spelling on the
    // rationale that "`str` is a reserved type keyword" so no user type could be
    // spelled bare. `str` is NOT a keyword -- it is a legal generic-parameter name,
    // and a `Ty::Param` renders BARE in every print mode. This compiles:
    //
    //     #![allow(non_camel_case_types)]
    //     pub fn attack<str: fmt::Display + ?Sized>(t: &str) -> String { t.to_string() }
    //
    // and its MIR calls `<str as ToString>::to_string` while `Self` is the caller's
    // choice. At a `Self` whose `Display` returns `Err`, the resolved body is the
    // `SpecToString` DEFAULT, which ends in `.expect(...)` and panics on every call.
    //
    // So this spelling carries NO panic-freedom information and must stay rejected.
    // A string gate cannot be made sound here: `Ty::Param("str")` and `TyKind::Str`
    // render identically. Re-admitting it requires an EXTRACTOR-SIDE stamp minted
    // from `TyCtxt` when the instantiated `Self` is `TyKind::Str`.
    assert!(!total("<str as alloc::string::ToString>::to_string"));
    assert!(!total("<str as std::string::ToString>::to_string"));
    assert!(!total(
        "<str as alloc::string::ToString>::to_string::<__trust_args@d440356f4eda3cbfcbc3129892185705>"
    ));

    // Still rejected for all the independent reasons the reverted arm also covered,
    // so a future re-attempt cannot regress these while chasing the spelling above.
    assert!(!total("<str as mycrate::ToString>::to_string"));
    assert!(!total("<String as alloc::string::ToString>::to_string"));
    assert!(!total("<core::io::error::Error as alloc::string::ToString>::to_string"));
    assert!(!total("mycrate::to_string"));
}

/// R41 — the SAME defect, three more times, now removed. REGRESSION PIN for
/// `PRIMITIVE_INT_SPELLINGS` + `is_primitive_int_{from_widening,ord_min_max,tryfrom}_callee`.
///
/// EVERY spelling below was produced by a REAL compilation on the deployed driver
/// (`~/.trust-tc-recon`, 2026-08-22), from a crate in which each `Self` (and each
/// `From`/`TryFrom` source) is a GENERIC PARAMETER, not the primitive it spells:
///
/// ```ignore (illustrative)
/// #![allow(non_camel_case_types)]
/// pub fn attack_ord_max<u64: Ord>(a: u64, b: u64) -> u64 { a.max(b) }
/// pub fn attack_ord_min<u64: Ord>(a: u64, b: u64) -> u64 { a.min(b) }
/// pub fn attack_from<u64, u8>(x: u8) -> u64 where u64: From<u8> { <u64 as From<u8>>::from(x) }
/// pub fn attack_tryfrom<u64, u32>(x: u32) -> Result<u64, <u64 as TryFrom<u32>>::Error>
/// where u64: TryFrom<u32> { <u64 as TryFrom<u32>>::try_from(x) }
/// ```
///
/// Instantiated at a local `Evil` whose `Ord::cmp` / `From::from` is `panic!()`, each
/// of those wrappers panics on EVERY input — `Ord::max` calls `Ord::cmp`, which is
/// USER code, and the core blanket `impl<T, U: Into<T>> TryFrom<U> for T` routes
/// `try_from` straight into the user `From`. With `TRUST_PF_MATCH_TRACE=1` the driver
/// printed `arm=bridge-total` for all three, i.e. the recognizers really did accept
/// the forgery in production.
///
/// The honest spellings are BYTE-IDENTICAL, which is the whole point: no predicate
/// over the rendered callee can separate `ty::Param("u64")` from `ty::Uint(U64)`.
/// The sound successor is the TyCtxt-anchored per-caller record
/// `typed_self_total_std_calls` (`typed_self_total_std_call`, gate arm
/// `typed-self-total`) in `rustc_mir_transform::trust_verify`.
#[test]
fn primitive_self_bare_spellings_are_forgeable() {
    use crate::lower::callee_is_recognized_total_no_panic as total;

    // The three FORGED spellings, exactly as the deployed driver rendered them.
    assert!(!total("<u64 as core::cmp::Ord>::max"));
    assert!(!total("<u64 as core::cmp::Ord>::min"));
    assert!(!total("<u64 as core::convert::From<u8>>::from"));
    assert!(!total("<u64 as core::convert::TryFrom<u32>>::try_from"));
    // …and the HONEST ones, which are the same bytes and so must fall with them.
    // A future re-admission that makes any of these `true` again has re-opened the
    // forgery; move the anchor to `TyCtxt` instead.
    assert!(!total("<usize as core::cmp::Ord>::max"));
    assert!(!total("<i64 as core::cmp::Ord>::min"));
    assert!(!total("<u128 as core::convert::From<u64>>::from"));
    assert!(!total("<u32 as core::convert::From<char>>::from"));
    assert!(!total("<u8 as core::convert::From<bool>>::from"));
    assert!(!total("<usize as core::convert::TryFrom<i128>>::try_from"));
    // The monomorph-tag and `__trust_crate@` disambiguated renderings of the same
    // call are not a way back in either.
    assert!(!total(
        "<usize as core::cmp::Ord>::max::<__trust_args@c8da168efb3f7e435104899fbc5ff592>"
    ));
    assert!(!total("__trust_crate@0123456789abcdef::<u64 as core::cmp::Ord>::max"));
    // Neighbouring stamped namespace must not cross-match into this family.
    assert!(!total("@trust-rustc-total-primitive-method::core::num::<impl u64>::max"));
    assert!(!total("@trust-rustc-wrapping-refutation-method::core::num::<impl u64>::wrapping_add"));
    // …while the wrapping family this file DOES admit stays admitted, so the removal
    // above is scoped to the three arms and did not collaterally retire LEVER 1.
    assert!(total("@trust-rustc-total-primitive-method::core::num::<impl u64>::wrapping_add"));
}

/// R42 REGRESSION PIN — was `range_uint_payload_anchor_is_forgeable_under_step_trait`,
/// which asserted `total(LIVE)` (the POSITIVE) and recorded the arm as a residual "held
/// closed by `Step` being unstable". BOTH the assertion and the rationale are now gone:
/// `PRIMITIVE_UINT_SPELLINGS` and `is_ops_range_uint_iterator_next_callee` are REMOVED.
///
/// THE ANCHOR WAS A RENDERED SUBSTRING. The arm peeled the `Self` spelling's trailing
/// angle group and tested `PRIMITIVE_UINT_SPELLINGS.contains(&payload.trim())` — six
/// words, no `TyCtxt`, no `TyKind`, no lang item, no extractor stamp. `usize` is a legal
/// generic-parameter name and a `ty::Param` renders BARE, so the honest and forged
/// callees are the SAME BYTES. Measured accepting the forgery on the deployed driver
/// (librustc_driver-ade33dacdb256b45):
///
/// ```text
/// [PF_ZEROGATE] fn=S::attack_range_nostep arm=bridge-total \
///   callee=<core::ops::range::Range<usize> as core::iter::traits::iterator::Iterator>::next
/// ```
///
/// THE OLD RATIONALE WAS REFUTED TWICE. (1) `#![feature(step_trait)]` is one line and
/// this workspace already enables `feature(contracts)`. (2) The forgery does not need
/// the feature at all — this compiles on stable-shaped input, never naming `Step`:
///
/// ```ignore (illustrative)
/// pub fn attack_range_nostep<usize>(r: &mut Range<usize>)
///     -> Option<<Range<usize> as Iterator>::Item>
/// where Range<usize>: Iterator { <Range<usize> as Iterator>::next(r) }
/// ```
///
/// At a payload whose `Step::forward_checked` returns `None`, core's default
/// `spec_next` (library/core/src/iter/range.rs:819-823) runs `.expect("`Step` invariants
/// not upheld")` — the accepted call panics on every input.
///
/// REMOVAL COST NOTHING HONEST: the TyCtxt-typed registry arm is consulted FIRST
/// (trust_verify.rs:18569 before :18575) and its `Range` test is a real `TyKind` test
/// (`inner(0) … matches!(t.kind(), ty::Int(_) | ty::Uint(_))`, trust_verify.rs:27412).
/// All four honest fixtures measured `arm=registry`, none `arm=bridge-total`.
#[test]
fn range_uint_payload_anchor_is_removed_and_stays_rejected() {
    use crate::lower::callee_is_recognized_total_no_panic as total;

    // The spelling the removed arm admitted. It is ALSO exactly what the forgery
    // renders, which is the whole point: no string gate can separate them, so the
    // honest one has to fall with the forged one. A future `assert!(total(LIVE))` here
    // has re-opened the hole — move the anchor to `TyCtxt` instead.
    const LIVE: &str =
        "<core::ops::range::Range<usize> as core::iter::traits::iterator::Iterator>::next";
    assert!(!total(LIVE), "the `Range<uN>::next` string arm is retired; TyCtxt owns this now");

    // ANTI-FORGERY (1): a generic parameter of the anchored name, every width the
    // removed `PRIMITIVE_UINT_SPELLINGS` carried — plus the `std::` re-export
    // rendering and the signed spellings, so no width or path variant sneaks back.
    for payload in ["u8", "u16", "u32", "u64", "u128", "usize", "i32", "isize"] {
        for path in [
            "core::ops::range::Range",
            "core::ops::Range",
            "std::ops::Range",
            "std::ops::range::Range",
        ] {
            assert!(
                !total(&format!(
                    "<{path}<{payload}> as core::iter::traits::iterator::Iterator>::next"
                )),
                "`{path}<{payload}>::next` must not be string-discharged"
            );
        }
    }

    // ANTI-FORGERY (2): the `__trust_crate@` impostor and the monomorph-tag rendering
    // of the same call are not a way back in.
    assert!(!total(
        "__trust_crate@0123456789abcdef::<core::ops::range::Range<usize> as \
         core::iter::traits::iterator::Iterator>::next"
    ));
    assert!(!total(
        "<core::ops::range::Range<usize> as core::iter::traits::iterator::Iterator>::next\
         ::<__trust_args@c8da168efb3f7e435104899fbc5ff592>"
    ));

    // ANTI-FORGERY (3): a path-mimicking module. A user crate may legally name modules
    // `ops::range` and a user type `Range`, and may name a type `usize`.
    for mimic in [
        "<mycrate::ops::range::Range<usize> as core::iter::traits::iterator::Iterator>::next",
        "<core::ops::range::Range<mycrate::usize> as core::iter::traits::iterator::Iterator>::next",
        "<core::ops::range::Range<usize> as mycrate::iter::traits::iterator::Iterator>::next",
        "<hostile::core::ops::range::Range<usize> as core::iter::traits::iterator::Iterator>::next",
    ] {
        assert!(!total(mimic), "path-mimicking spelling `{mimic}` must not be discharged");
    }

    // A non-primitive payload was refused before and still is — but note that this was
    // never the load-bearing part: the arm's failure mode was accepting a `ty::Param`
    // that HAPPENED to be spelled like a primitive, not accepting an honestly-spelled
    // user type.
    assert!(!total(
        "<core::ops::range::Range<mycrate::MyStep> as core::iter::traits::iterator::Iterator>::next"
    ));

    // The SIBLING `IntoIterator::into_iter` identity arm is deliberately UNTOUCHED — it
    // has no payload anchor at all (the blanket `impl<I: Iterator> IntoIterator for I`
    // body is the identity `fn into_iter(self) -> I { self }`, total for every payload),
    // so this removal is scoped to the `next` arm and did not collaterally retire it.
    assert!(total(
        "<core::ops::range::Range<usize> as core::iter::traits::collect::IntoIterator>::into_iter"
    ));
}

// Round-4 (sort-comparator seam): the family recognizer is a SHAPE gate only —
// it may never grant totality by itself, and the composite string gate must
// keep REJECTING a closure-carrying sort spelling (the discharge exists ONLY in
// the compiler-side seam that additionally requires the bundled comparator
// closure to pass the audited FIX B classifier).
#[test]
fn sort_comparator_family_is_shape_only_and_never_string_total() {
    use crate::lower::{
        callee_is_recognized_total_no_panic as total,
        callee_is_slice_sort_comparator_family as family,
    };

    // The EXACT certify_upper_inner blocker spelling (gateLCG census).
    const CENSUS_SORT_BY: &str = "alloc::slice::<impl [usize]>::sort_by::<{closure@crates/ny-cert/src/sbar.rs:303:23: 303:31}>::<__trust_args@32705ccc06e1bf27852e7c13dacbf08c>";

    // Family SHAPE matches (std-rooted ::slice:: tail, all four members):
    assert!(family(CENSUS_SORT_BY));
    assert!(family("core::slice::<impl [u64]>::sort_unstable_by"));
    assert!(family("alloc::slice::<impl [usize]>::sort_by_key"));
    assert!(family("alloc::slice::<impl [usize]>::sort_unstable_by_key"));
    // Family REJECTS: user shadow, plain sort, cached-key sibling, non-slice tail.
    assert!(!family("mycrate::slice::sort_by"));
    assert!(!family("mycrate::alloc::slice::sort_by"));
    assert!(!family("alloc::slice::<impl [usize]>::sort"));
    assert!(!family("alloc::slice::<impl [usize]>::sort_by_cached_key"));
    assert!(!family("alloc::vec::Vec::sort_by"));

    // THE LOCK: the string-only composite gate must NOT admit ANY sort-family
    // spelling — with or without the closure turbofish — no matter that the
    // family shape matches. Totality here requires the compiler-side seam's
    // classified-closure conjunct, which a string can never carry.
    assert!(!total(CENSUS_SORT_BY));
    assert!(!total("alloc::slice::<impl [usize]>::sort_by"));
    assert!(!total("core::slice::<impl [u64]>::sort_unstable_by"));
    assert!(!total("alloc::slice::<impl [usize]>::sort_by_key"));
    // Belt: a forged closure turbofish on a NON-family callee grants nothing.
    assert!(!total("mycrate::slice::sort_by::<{closure@src/x.rs:1:1: 1:9}>"));
}

// ─── copy_nonoverlapping ────────────────────────────────────────────────────
//
// rustc's `LowerIntrinsics` pass rewrites `copy_nonoverlapping(src, dst, count)`
// into `NonDivergingIntrinsic::CopyNonOverlapping` before Trust ever sees a body,
// so this is the spelling EVERY std body carries (`ptr::read`,
// `MaybeUninit::assume_init`, `mem::replace`, `RawVecInner::with_capacity_in`,
// `alloc::fmt::format`, …). It used to reach the bridge as
// `Statement::Unsupported` and abort the WHOLE function's lowering with
// "memory copy side effects require explicit memory-model lowering".

/// Build `fn f(src: *const T, dst: *mut T) { copy_nonoverlapping(src, dst, count) }`.
fn copy_nonoverlapping_func(elem_ty: Ty, count: Operand) -> VerifiableFunction {
    VerifiableFunction {
        name: "cno".to_string(),
        def_path: "test::cno".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl {
                    index: 1,
                    ty: Ty::RawPtr { mutable: false, pointee: Box::new(elem_ty.clone()) },
                    name: Some("src".into()),
                },
                LocalDecl {
                    index: 2,
                    ty: Ty::RawPtr { mutable: true, pointee: Box::new(elem_ty.clone()) },
                    name: Some("dst".into()),
                },
            ],
            blocks: vec![TrustBlock {
                id: BlockId(0),
                stmts: vec![Statement::CopyNonOverlapping {
                    src: Operand::Copy(Place::local(1)),
                    dst: Operand::Copy(Place::local(2)),
                    count,
                    elem_ty,
                    span: SourceSpan::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 2,
            return_ty: Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    }
}

fn count_insts(module: &trust_ir::Module, mut pred: impl FnMut(&Inst) -> bool) -> usize {
    module
        .functions
        .iter()
        .flat_map(|f| f.blocks.iter())
        .flat_map(|b| b.body.iter())
        .filter(|node| pred(&node.inst))
        .count()
}

/// A constant-count copy lowers into the ORDINARY memory model — one `Load` and
/// one `Store` per element — instead of aborting the function.
///
/// The `Store` count is the load-bearing assertion, and it is exactly the
/// anti-staleness property: the real copy overwrites all `count` elements, so a
/// model that emitted FEWER stores would leave the elements it skipped holding
/// their pre-copy value and let a later read of the destination return a stale
/// one. (That is the shape the `GEP`-derived-store audit found in
/// `translate_chc.rs`: a dropped write with a surviving precise cell.)
#[test]
fn copy_nonoverlapping_const_count_lowers_to_one_load_store_per_element() {
    for count in [1u128, 2, 5] {
        let func =
            copy_nonoverlapping_func(Ty::u32(), Operand::Constant(ConstValue::Uint(count, 64)));
        let module = lower_to_trust_ir(&func)
            .unwrap_or_else(|e| panic!("count={count} must lower, not Err: {e:?}"));
        assert_valid_module(&module);

        let loads = count_insts(&module, |i| matches!(i, Inst::Load { .. }));
        let stores = count_insts(&module, |i| matches!(i, Inst::Store { .. }));
        assert_eq!(loads, count as usize, "count={count}: one Load per element");
        assert_eq!(
            stores, count as usize,
            "count={count}: one Store per element — a missing store is a stale destination read"
        );
        // Element 0 addresses the base pointer directly; every later element
        // needs its own `GEP`, on BOTH sides.
        let geps = count_insts(&module, |i| matches!(i, Inst::GEP { .. }));
        assert_eq!(geps, 2 * (count as usize - 1), "count={count}: GEP per non-zero element");
    }
}

/// Every element is LOADED before any element is STORED, so the modeled
/// post-state is the copy-through-a-temporary one. That agrees with the real
/// intrinsic on its documented (non-overlapping) domain WITHOUT depending on the
/// non-overlap obligation having been discharged first.
#[test]
fn copy_nonoverlapping_loads_all_elements_before_storing_any() {
    let func = copy_nonoverlapping_func(Ty::u32(), Operand::Constant(ConstValue::Uint(3, 64)));
    let module = lower_to_trust_ir(&func).expect("must lower");
    let kinds: Vec<&'static str> = module
        .functions
        .iter()
        .flat_map(|f| f.blocks.iter())
        .flat_map(|b| b.body.iter())
        .filter_map(|node| match &node.inst {
            Inst::Load { .. } => Some("load"),
            Inst::Store { .. } => Some("store"),
            _ => None,
        })
        .collect();
    let first_store = kinds.iter().position(|k| *k == "store").expect("a store must be emitted");
    let last_load = kinds.iter().rposition(|k| *k == "load").expect("a load must be emitted");
    assert!(last_load < first_store, "all loads must precede all stores, got {kinds:?}");
}

/// R129: the soundness core of the symbolic-count lowering, updated from the
/// historical fail-closed refusal. A symbolic count writes an unbounded
/// region; modeling fewer elements than are written is a false-proof
/// generator (the stale-read shape `copy_nonoverlapping_stale_read.rs`
/// canaries). The sound model is now the MARKED REGION-HAVOC STORE: a fresh
/// Undef element written through a fresh-symbolic index off `dst`, carrying
/// `ProofAnnotation::RegionHavocStore`. The CHC lane degrades that store to
/// whole-tracked-cell invalidation (its audited over-approximation); the BMC
/// lane — whose SMT-array memory would under-approximate the write set —
/// FAILS CLOSED on the marker
/// (`region_havoc_store_fails_closed_in_bmc_and_only_when_marked` in
/// trust-mc pins that half). This test pins the PRODUCER half: the lowering
/// succeeds, emits exactly one store, that store carries the marker, and no
/// unmarked partial element model (loads from `src`, count-bounded stores)
/// is emitted alongside it.
#[test]
fn copy_nonoverlapping_symbolic_count_emits_marked_region_havoc_store() {
    let mut func = copy_nonoverlapping_func(Ty::u32(), Operand::Copy(Place::local(3)));
    func.body.locals.push(LocalDecl { index: 3, ty: Ty::usize(), name: Some("count".into()) });
    func.body.arg_count = 3;
    let module = lower_to_trust_ir(&func)
        .expect("a symbolic element count must lower via the marked region-havoc store");
    let stores: Vec<_> = module
        .functions
        .iter()
        .flat_map(|f| f.blocks.iter())
        .flat_map(|b| b.body.iter())
        .filter(|node| matches!(&node.inst, Inst::Store { .. }))
        .collect();
    assert_eq!(stores.len(), 1, "exactly one region-havoc store, no partial element model");
    assert!(
        stores[0].proofs.contains(&trust_ir::ProofAnnotation::RegionHavocStore),
        "the store must carry RegionHavocStore — an unmarked store would translate \
         normally in the BMC lane and resurrect the stale-read false proof"
    );
    let loads = module
        .functions
        .iter()
        .flat_map(|f| f.blocks.iter())
        .flat_map(|b| b.body.iter())
        .filter(|node| matches!(&node.inst, Inst::Load { .. }))
        .count();
    assert_eq!(loads, 0, "reads from src must stay unmodeled (they constrain nothing)");
}

/// The unroll budget is a real bound, not decoration: past it the lowering fails
/// closed rather than inflating one statement into thousands of instructions.
#[test]
fn copy_nonoverlapping_over_budget_count_fails_closed() {
    let func = copy_nonoverlapping_func(Ty::u8(), Operand::Constant(ConstValue::Uint(4096, 64)));
    let err = lower_to_trust_ir(&func).expect_err("an over-budget count must fail closed");
    assert!(matches!(err, BridgeError::UnsupportedOp(_)), "expected UnsupportedOp, got {err:?}");
}

#[test]
fn copy_nonoverlapping_over_budget_zero_sized_element_is_noop() {
    let func = copy_nonoverlapping_func(Ty::Unit, Operand::Constant(ConstValue::Uint(65, 64)));
    let module = lower_to_trust_ir(&func).expect("a zero-sized copy has no elements to unroll");
    assert_valid_module(&module);
    assert_eq!(count_insts(&module, |i| matches!(i, Inst::Load { .. })), 0);
    assert_eq!(count_insts(&module, |i| matches!(i, Inst::Store { .. })), 0);
    assert_eq!(count_insts(&module, |i| matches!(i, Inst::GEP { .. })), 0);
}

/// Trust: body-less intrinsics can never be bundled, so an absent-callee obligation
/// on one is permanent — a model is the only route. `orca-provider-backoff` verified
/// clean, then regressed to 2 errors on `core::intrinsics::saturating_sub::<u32>`
/// alone, in a function already hand-rewritten once to dodge an absent callee.
#[test]
fn saturating_intrinsics_are_total_but_unchecked_ones_are_not() {
    use crate::lower::total_no_panic_call_summary;
    const P: &str = trust_types::TRUST_RUSTC_INTRINSIC_PATH_PREFIX;

    // Saturating clamps at the type bound instead of overflowing — total by definition.
    // (`saturating_mul` is no intrinsic of this tree's `core`; its dead entry left the
    // list in std-call-summaries P2.)
    for name in ["saturating_add", "saturating_sub"] {
        let callee = format!("{P}core::intrinsics::{name}::<u32>");
        assert!(
            total_no_panic_call_summary(&callee),
            "{name} clamps rather than overflowing and must be total"
        );
    }

    // Pure functions of the bit pattern; no partial cases.
    for name in ["ctpop", "ctlz", "cttz", "bswap", "bitreverse"] {
        let callee = format!("{P}core::intrinsics::{name}::<u64>");
        assert!(total_no_panic_call_summary(&callee), "{name} is total");
    }

    // Trust (std-call-summaries P2): names the deterministic marker never stamps
    // left this list (they were dead TCB entries). The rotations are panic-free,
    // but their fallback body calls the unchecked `unchecked_funnel_sh*`, so no
    // stamp admits them; the nondeterministic and fallback-bodied float intrinsics
    // moved to the panic-freedom-only stamp, and the deterministic spelling of them
    // must stay refused so it can never be read as a determinism claim.
    for name in [
        "saturating_mul",
        "rotate_left",
        "rotate_right",
        "size_of",
        "align_of",
        "min_align_of",
        "fabsf64",
        "rintf64",
        "minnumf64",
        "maxnumf64",
        "sinf64",
        "powif64",
        "minimumf64",
        "maximum_number_nsz_f64",
    ] {
        let callee = format!("{P}core::intrinsics::{name}");
        assert!(!total_no_panic_call_summary(&callee), "{name} must not be total by this list");
    }
    // And the whole panic-freedom-only list, by construction: a name may not be on
    // both. With the bridge list clean, an intrinsic that the extractor ALSO puts on
    // the deterministic marker takes the absent-callee arm, which is what turns
    // `float_inexact_intrinsic_methods_stay_refused.rs#no_census` and
    // `f64_method_requires_exact_std_path.rs` red end to end (std-call-summaries P2
    // review, mutation-checked on a stage 1 with `expf64` added to the marker).
    for entry in trust_types::PANIC_FREE_RUSTC_INTRINSICS {
        let callee = format!("{P}core::intrinsics::{}", entry.name);
        assert!(
            !total_no_panic_call_summary(&callee),
            "{} is panic-freedom-only and must not be total under the deterministic marker",
            entry.name
        );
    }

    // The fail-closed half. Each of these carries a precondition a caller can
    // violate, so modeling it total would launder UB into a proof.
    for name in [
        "unchecked_add",
        "unchecked_sub",
        "unchecked_mul",
        "unchecked_shl",
        "ctlz_nonzero",
        "cttz_nonzero",
        "arith_offset",
        "ptr_offset_from_unsigned",
        "assume",
        "unreachable",
    ] {
        let callee = format!("{P}core::intrinsics::{name}::<u32>");
        assert!(
            !total_no_panic_call_summary(&callee),
            "{name} has a precondition and must NOT be assumed total"
        );
    }

    // The marker is what admits these; a same-named user path must not ride in.
    assert!(!total_no_panic_call_summary("mycrate::intrinsics::saturating_sub"));

    // Codegen hints run no code at all. `cold_path` is what surfaced once
    // `saturating_sub` was modeled — one absent callee hiding behind another.
    for hint in [
        "core::intrinsics::cold_path",
        "core::intrinsics::likely",
        "core::intrinsics::unlikely",
        "core::hint::black_box",
        "core::hint::spin_loop",
    ] {
        assert!(total_no_panic_call_summary(hint), "{hint} runs no code");
    }
}

/// A VIRTUAL (`dyn`-receiver) call must be refused with a reason that names the
/// receiver, and must NOT be described as a missing body: no MIR-encoding flag,
/// bundle-cap raise, or crate-filter widening can supply a body for a vtable
/// slot, so that wording sends every reader after a fix that cannot exist.
///
/// Every non-`dyn` absent callee keeps its previous wording byte-for-byte —
/// this is a per-site refusal, not a reclassification of the absent-callee arm.
#[test]
fn dyn_receiver_absent_callee_reason_names_the_receiver() {
    use crate::lower::{absent_callee_reason, dyn_receiver_of_virtual_callee};

    // The two floors measured in the fmt chain.
    for (callee, receiver) in [
        ("<dyn core::fmt::Write as core::fmt::Write>::write_str", "dyn core::fmt::Write"),
        ("<dyn core::fmt::Debug as core::fmt::Debug>::fmt", "dyn core::fmt::Debug"),
    ] {
        assert_eq!(dyn_receiver_of_virtual_callee(callee), Some(receiver));
        let reason = absent_callee_reason(callee, None);
        assert!(reason.contains(receiver), "reason must name the receiver: {reason}");
        assert!(
            !reason.contains("body not in the lowered bundle"),
            "a vtable slot has no body to be missing: {reason}"
        );
    }

    // Not virtual: a concrete impl, a still-generic receiver, and a free fn all
    // keep the original text.
    for callee in [
        "core::num::u32::pow",
        "<u32 as core::ops::Add>::add",
        "<T as core::fmt::Write>::write_str",
        "<dynamo::Thing as dynamo::Trait>::go", // `dyn`-prefixed NAME, not a dyn receiver
    ] {
        assert_eq!(dyn_receiver_of_virtual_callee(callee), None, "{callee}");
        assert_eq!(
            absent_callee_reason(callee, None),
            "body not in the lowered bundle",
            "{callee}"
        );
    }
}

// ---------------------------------------------------------------------------
// Trust (coroutine resume-state contract): the lowering-side pins. The model
// fixture mirrors rustc's zero-await `async fn` resume body — entry dispatch
// `_3 = discriminant((*_1)); switchInt(_3) -> [0: body, 1: sink, 2: sink,
// otherwise: unreachable]` with the extractor's `exhaustive_enum_unreachable`
// certificate set — plus the two `ResumedAfter*` self-loop protocol sinks.
// What the stage2 run must additionally confirm (cannot run here): the counted
// carrier surfaces the sentinel obligations, the native lane PROVES them under
// `-Ztrust-policy=certify`, and the compiler publishes exactly one
// `contract:coroutine-resume-state` row for the proved fixture.
// ---------------------------------------------------------------------------

fn coroutine_resume_fixture(certified: bool) -> VerifiableFunction {
    use trust_types::AssertMessage;
    let frame_ty = Ty::Ref {
        mutable: true,
        inner: Box::new(Ty::Coroutine {
            name: "fixture::f::{closure#0}".into(),
            upvars: vec![Ty::u8()],
        }),
    };
    let sentinel = |id: usize, msg: AssertMessage| TrustBlock {
        id: BlockId(id),
        stmts: vec![],
        terminator: Terminator::Assert {
            cond: Operand::Constant(ConstValue::Bool(false)),
            expected: true,
            msg,
            // rustc emits the protocol sink as a SELF-LOOP.
            target: BlockId(id),
            span: SourceSpan::default(),
            unwind: UnwindEdge::Unreachable,
        },
    };
    VerifiableFunction {
        name: "fixture::f::{closure#0}".to_string(),
        def_path: "fixture::f::{closure#0}".to_string(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::u16(), name: None },
                LocalDecl { index: 1, ty: frame_ty, name: Some("self".into()) },
                LocalDecl { index: 2, ty: Ty::u32(), name: None },
                LocalDecl { index: 3, ty: Ty::u32(), name: None },
            ],
            blocks: vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(3),
                        rvalue: Rvalue::Discriminant(Place {
                            local: 1,
                            projections: vec![Projection::Deref],
                        }),
                        span: SourceSpan::default(),
                    }],
                    terminator: Terminator::SwitchInt {
                        discr: Operand::Copy(Place::local(3)),
                        targets: vec![(0, BlockId(1)), (1, BlockId(2)), (2, BlockId(3))],
                        otherwise: BlockId(4),
                        exhaustive_enum_unreachable: certified,
                        span: SourceSpan::default(),
                    },
                },
                TrustBlock {
                    id: BlockId(1),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Uint(1, 16))),
                        span: SourceSpan::default(),
                    }],
                    terminator: Terminator::Return,
                },
                sentinel(2, AssertMessage::ResumedAfterReturn),
                sentinel(3, AssertMessage::ResumedAfterPanic),
                TrustBlock { id: BlockId(4), stmts: vec![], terminator: Terminator::Unreachable },
            ],
            arg_count: 2,
            return_ty: Ty::u16(),
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    }
}

/// Under the recognized entry contract, the dispatch read gains exactly one
/// `Assume(selector == 0)` (zero-await live set {0}) and the sentinels become
/// REFUTABLE `Inst::Assert`s carrying marker-stamped PanicFreedom obligations
/// plus the whole-function counted carrier.
#[test]
fn coroutine_contract_entry_read_emits_live_state_assume_and_refutable_sentinels() {
    let func = coroutine_resume_fixture(true);
    let module = lower_to_trust_ir(&func).expect("contract fixture must lower");
    let f = &module.functions[0];

    let entry = &f.blocks[0];
    let assumes: Vec<_> =
        entry.body.iter().filter(|n| matches!(&n.inst, Inst::Assume { .. })).collect();
    // TWO assumes, from two independent lanes: the live-state contract Assume
    // at the dispatch read (this lane) plus the pre-existing exhaustive-switch
    // case-set Assume the `exhaustive_enum_unreachable` SwitchInt lowering
    // emits for its Unreachable otherwise arm. The uncertified twin below pins
    // zero, so the delta attributable to the certificate is exactly these two.
    assert_eq!(assumes.len(), 2, "live-state Assume + exhaustive-switch case Assume");
    assert!(
        entry.body.iter().any(|n| matches!(&n.inst, Inst::ICmp { op: ICmpOp::Eq, .. })),
        "the live-state Assume must be built from an equality against the live state"
    );

    // Sentinel blocks: refutable Assert, NOT the by-construction Assume(false).
    let sink_blocks: Vec<_> = f.blocks.iter().filter(|b| b.id.0 == 2 || b.id.0 == 3).collect();
    assert_eq!(sink_blocks.len(), 2);
    for bb in sink_blocks {
        assert!(
            bb.body.iter().any(|n| matches!(&n.inst, Inst::Assert { .. })),
            "protocol sink block {} must carry a refutable Assert under the contract",
            bb.id.0
        );
        assert!(
            !bb.body.iter().any(|n| matches!(&n.inst, Inst::Assume { .. })),
            "protocol sink block {} must not keep the Assume(false) pruning",
            bb.id.0
        );
    }

    // Marker-stamped sentinel obligations with the exact state set.
    let marked: Vec<_> = module
        .proof_obligations
        .iter()
        .filter(|ob| {
            ob.description
                .starts_with(trust_types::assumption::COROUTINE_RESUME_CONTRACT_OBLIGATION_PREFIX)
        })
        .collect();
    assert_eq!(marked.len(), 2, "one obligation per ResumedAfter* sentinel");
    for ob in &marked {
        let (states, _sentinel) =
            trust_types::assumption::parse_coroutine_resume_contract_obligation_description(
                &ob.description,
            )
            .expect("marker description must round-trip");
        assert_eq!(states, vec![0], "zero-await live set is exactly {{0}}");
    }

    // The counted whole-function carrier must exist: without it the sentinel
    // rows would live only in module.proof_obligations (the R3 fail-open).
    assert!(
        module.proof_obligations.iter().any(|ob| ob.description.ends_with(": all assertions hold")),
        "contract-lowered coroutine must emit the whole-function panic-freedom carrier"
    );
}

/// Without the extractor's exhaustiveness certificate the contract lane must
/// not engage: byte-for-byte today's fail-closed shape (havoc'd selector, no
/// Assume at the read, Assume(false)-pruned sinks, zero marker obligations).
#[test]
fn coroutine_without_certificate_keeps_fail_closed_pruning() {
    let func = coroutine_resume_fixture(false);
    let module = lower_to_trust_ir(&func).expect("uncertified fixture must still lower");
    let f = &module.functions[0];

    let entry = &f.blocks[0];
    assert!(
        !entry.body.iter().any(|n| matches!(&n.inst, Inst::Assume { .. })),
        "no contract => the havoc'd selector must carry no Assume"
    );
    let sink_blocks: Vec<_> = f.blocks.iter().filter(|b| b.id.0 == 2 || b.id.0 == 3).collect();
    for bb in sink_blocks {
        assert!(
            bb.body.iter().any(|n| matches!(&n.inst, Inst::Assume { .. })),
            "protocol sink block {} must keep the fail-closed Assume(false) pruning",
            bb.id.0
        );
        assert!(
            !bb.body.iter().any(|n| matches!(&n.inst, Inst::Assert { .. })),
            "no contract => no refutable sentinel Assert (it would falsely refute)",
        );
    }
    assert!(
        !module.proof_obligations.iter().any(|ob| {
            ob.description
                .starts_with(trust_types::assumption::COROUTINE_RESUME_CONTRACT_OBLIGATION_PREFIX)
        }),
        "no contract => no marker obligations"
    );
    assert_eq!(
        crate::lower::coroutine_resume_contract_module_evidence(&func, &module),
        None,
        "no contract => no module evidence"
    );
}

